# --- COMPATIBILITÉ RÉSOLUTIONS / DPI (Windows 10 & 11, petits écrans comme 4K) ---
# CustomTkinter déclare déjà l'app "DPI aware" tout seul à son import (ci-dessus), mais cet
# appel explicite sert de filet de sécurité si une future version de la librairie change de
# comportement, et demande en priorité le mode "par moniteur" (le plus correct quand plusieurs
# écrans ont des échelles DPI différentes). Chaque tentative est silencieuse si elle échoue :
# un appel redondant à SetProcessDpiAwareness renvoie juste une erreur sans planter le process.
def _forcer_dpi_awareness():
    try:
        # Windows 10 1703+ : conscience DPI par moniteur, la plus précise.
        DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2 = ctypes.c_void_p(-4)
        ctypes.windll.user32.SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2)
        return
    except Exception:
        pass
    try:
        # Windows 8.1+ : conscience DPI système (repli si l'API par moniteur est absente).
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
        return
    except Exception:
        pass
    try:
        # Windows Vista/7 : dernier repli, conscience DPI basique.
        ctypes.windll.user32.SetProcessDPIAware()
    except Exception:
        pass

_forcer_dpi_awareness()

