# --- Bannière du logiciel (miniature intégrée, aucun fichier externe) ---
BANNIERE_B64 = ""

def charger_banniere(hauteur=60):
    """Renvoie une CTkImage de la bannière (ou None en cas de problème)."""
    try:
        import base64, io
        img = Image.open(io.BytesIO(base64.b64decode(BANNIERE_B64))).convert("RGB")
        ratio = hauteur / img.height
        return ctk.CTkImage(light_image=img, dark_image=img, size=(int(img.width * ratio), hauteur))
    except Exception:
        return None

# --- Drapeaux dessinés par le code (les emoji drapeaux s'affichent en lettres sous Windows) ---
from PIL import ImageDraw

def _vstripes(d, W, H, cols):
    n = len(cols)
    for i, c in enumerate(cols):
        d.rectangle((i*W//n, 0, (i+1)*W//n, H), fill=c)

def _hstripes(d, W, H, cols, ratios=None):
    ratios = ratios or [1]*len(cols); tot = sum(ratios); y = 0
    for c, r in zip(cols, ratios):
        h = H*r/tot; d.rectangle((0, y, W, y+h+1), fill=c); y += h

def _union_jack(d, W, H):
    blue, red, white = (1,33,105), (200,16,46), (255,255,255)
    d.rectangle((0,0,W,H), fill=blue)
    for sx, sy, ex, ey in ((0,0,W,H),(0,H,W,0)):
        d.line((sx,sy,ex,ey), fill=white, width=int(H*0.20))
    for sx, sy, ex, ey in ((0,0,W,H),(0,H,W,0)):
        d.line((sx,sy,ex,ey), fill=red, width=int(H*0.07))
    d.rectangle((0, H*0.5-H*0.17, W, H*0.5+H*0.17), fill=white)
    d.rectangle((W*0.5-W*0.14, 0, W*0.5+W*0.14, H), fill=white)
    d.rectangle((0, H*0.5-H*0.10, W, H*0.5+H*0.10), fill=red)
    d.rectangle((W*0.5-W*0.08, 0, W*0.5+W*0.08, H), fill=red)

def fabriquer_drapeau(code, largeur=48, hauteur=32):
    """Drapeau dessiné en code (aucun fichier externe). Renvoie une image PIL RGBA aux coins arrondis."""
    k = 6
    W, H = largeur*k, hauteur*k
    fl = Image.new("RGBA", (W, H), (255,255,255,255)); d = ImageDraw.Draw(fl)
    if code == "fr":
        _vstripes(d, W, H, [(0,85,164),(255,255,255),(239,65,53)])
    elif code == "de":
        _hstripes(d, W, H, [(0,0,0),(221,0,0),(255,206,0)])
    elif code == "it":
        _vstripes(d, W, H, [(0,146,70),(255,255,255),(206,43,55)])
    elif code == "es":
        _hstripes(d, W, H, [(170,21,27),(241,191,0),(170,21,27)], [1,2,1])
    elif code == "en":
        _union_jack(d, W, H)
    else:
        d.rectangle((0,0,W,H), fill=(90,100,115))
    # léger relief : reflet haut + liseré
    ov = Image.new("RGBA", (W, H), (0,0,0,0)); od = ImageDraw.Draw(ov)
    for y in range(H//2):
        od.line((0,y,W,y), fill=(255,255,255,int(34*(1-y/(H/2)))))
    fl = Image.alpha_composite(fl, ov)
    m = Image.new("L", (W, H), 0); ImageDraw.Draw(m).rounded_rectangle((0,0,W-1,H-1), radius=int(H*0.16), fill=255)
    out = Image.new("RGBA", (W, H), (0,0,0,0)); out.paste(fl, (0,0), m)
    ImageDraw.Draw(out).rounded_rectangle((0,0,W-1,H-1), radius=int(H*0.16), outline=(255,255,255,70), width=max(2, k//2))
    return out.resize((largeur, hauteur), Image.LANCZOS)



NOMS_LANGUES = {"fr": "Français", "en": "English", "de": "Deutsch", "es": "Español", "it": "Italiano"}

def charger_drapeau(code, largeur=45, hauteur=30):
    """CTkImage du drapeau de la langue (ou None si impossible)."""
    try:
        img = fabriquer_drapeau(code, largeur * 3, hauteur * 3)
        return ctk.CTkImage(light_image=img, dark_image=img, size=(largeur, hauteur))
    except Exception:
        return None


