FENETRE_LARGEUR = 1040
FENETRE_HAUTEUR_MIN = 620  # la hauteur par défaut est calculée : toute la zone utile de l'écran


def choisir(lang, fr, en=None, de=None, es=None, it=None):
    """Retourne le texte dans la langue demandée.
    Repli : anglais, puis français (langue sans traduction)."""
    textes = {"fr": fr, "en": en, "de": de, "es": es, "it": it}
    texte = textes.get(lang)
    if texte is None:
        texte = en if en is not None else fr
    return texte



def get_assets_path():
    if hasattr(sys, "_MEIPASS"):
        return os.path.join(sys._MEIPASS, "assets_arcade")
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets_arcade")


def get_resource_path(relative_path):
    if hasattr(sys, '_MEIPASS'):
        return os.path.join(sys._MEIPASS, relative_path)
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), relative_path)


def get_zone_utile():
    """Zone de travail de l'écran principal (hors barre des tâches)."""
    try:
        rect = ctypes.wintypes.RECT()
        ctypes.windll.user32.SystemParametersInfoW(48, 0, ctypes.byref(rect), 0)  # SPI_GETWORKAREA
        return rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top
    except Exception:
        return None


def centrer_fenetre(win, largeur, hauteur):
    """Centre une fenêtre CTk/CTkToplevel quelle que soit la résolution et l'échelle DPI."""
    win.update_idletasks()
    scale = win._get_window_scaling() if hasattr(win, "_get_window_scaling") else 1.0
    zx, zy, zl, zh = get_zone_utile() or (0, 0, win.winfo_screenwidth(), win.winfo_screenheight())

    # Si l'écran est trop petit, on réduit la fenêtre (marge de 20 px)
    largeur = min(largeur, int((zl - 20) / scale))
    hauteur = min(hauteur, int((zh - 20) / scale))

    x = zx + int((zl - largeur * scale) / 2)
    y = zy + int((zh - hauteur * scale) / 2)
    win.geometry(f"{largeur}x{hauteur}+{x}+{y}")


def hauteur_decorations(win):
    """Hauteur réelle (px) de la barre de titre + bordures d'une fenêtre Windows, ou None si indisponible."""
    try:
        user32 = ctypes.windll.user32
        hwnd = user32.GetParent(win.winfo_id()) or win.winfo_id()
        style = user32.GetWindowLongW(hwnd, -16) & 0xFFFFFFFF      # GWL_STYLE
        exstyle = user32.GetWindowLongW(hwnd, -20) & 0xFFFFFFFF    # GWL_EXSTYLE
        dpi = user32.GetDpiForWindow(hwnd)
        rect = ctypes.wintypes.RECT(0, 0, 0, 0)
        if not dpi or not user32.AdjustWindowRectExForDpi(ctypes.byref(rect), style, False, exstyle, dpi):
            return None
        deco = rect.bottom - rect.top
        return deco if 20 <= deco <= 200 else None
    except Exception:
        return None


def fenetre_pleine_hauteur(win, largeur):
    """Centre la fenêtre horizontalement et la fait occuper toute la hauteur de la zone utile
    (écran moins barre des tâches). Retourne (largeur, hauteur) en pixels logiques."""
    win.update_idletasks()
    scale = win._get_window_scaling() if hasattr(win, "_get_window_scaling") else 1.0
    zx, zy, zl, zh = get_zone_utile() or (0, 0, win.winfo_screenwidth(), win.winfo_screenheight())

    deco = hauteur_decorations(win)
    if deco is None:
        deco = int(40 * scale)  # estimation si Windows ne répond pas

    largeur = min(largeur, int((zl - 20) / scale))
    hauteur = int((zh - deco) / scale)

    x = zx + int((zl - largeur * scale) / 2)
    win.geometry(f"{largeur}x{hauteur}+{x}+{zy}")
    return largeur, hauteur


def charger_config_contact():
    """Charge l'adresse mail depuis le fichier externe config_contact.json dans assets_arcade si présent."""
    config_path = os.path.join(get_assets_path(), "config_contact.json")
    default_email = "ATELIER.PC.BOOSTER.PRO.v5@gmx.fr"
    if os.path.exists(config_path):
        try:
            with open(config_path, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data.get("email", default_email)
        except Exception:
            pass
    return default_email


