    # ------------------------------------------------------------------ mise en page « cartes colorées »
    def _notice_largeur(self):
        return FENETRE_LARGEUR - 150

    def _notice_police(self, base, gras=False):
        return ctk.CTkFont(size=max(9, int(round(base * self.notice_zoom))), weight="bold" if gras else "normal")

    def _notice_onglet_change(self):
        try:
            idx = self.tab_names.index(self.notice_tabview.get()) + 1
        except Exception:
            return
        self._construire_vue_notice(idx)

    def _notice_zoomer(self, delta):
        nouveau = round(min(1.4, max(0.8, self.notice_zoom + delta)), 2)
        if nouveau == self.notice_zoom:
            return
        self.notice_zoom = nouveau
        self.notice_vues_ok.clear()
        self._notice_onglet_change()

    def _construire_vue_notice(self, idx):
        if idx in self.notice_vues_ok or idx not in self.notice_vues:
            return
        self.notice_vues_ok.add(idx)
        cadre = self.notice_vues[idx]
        try:
            for w in cadre.winfo_children():
                w.destroy()
        except Exception:
            pass
        self.notice_index[idx] = []
        blocs = analyser_notice(getattr(self, f"txt_{idx}").get("1.0", "end"))
        L = self._notice_largeur()
        carte = None          # (cadre, type, largeur de texte)
        teinte = None

        def fermer():
            nonlocal carte, teinte
            carte = None
            teinte = None

        def parent():
            return carte[0] if carte else cadre

        def largeur_texte():
            return (L - 44) if carte else L

        def lab(master, texte, taille, couleur, gras=False, wrap=None, **kw):
            lb = ctk.CTkLabel(master, text=texte, font=self._notice_police(taille, gras), text_color=couleur,
                              justify="left", anchor="w", wraplength=wrap or largeur_texte(), **kw)
            return lb

        for type_, texte, retrait in blocs:
            if type_ == "title":
                Lt = FENETRE_LARGEUR - 95  # le bandeau occupe toute la largeur utile
                img = ctk.CTkImage(light_image=degrade_titre_notice(Lt), dark_image=degrade_titre_notice(Lt), size=(Lt, 58))
                ctk.CTkLabel(cadre, text="   " + texte, image=img, compound="center", anchor="w",
                             font=self._notice_police(20, True), text_color="#FFFFFF").pack(anchor="w", padx=8, pady=(10, 14))
                self.notice_index[idx].append((None, texte.lower()))
            elif type_ == "sep":
                fermer()
            elif type_ == "h1":
                fermer()
                ligne = ctk.CTkFrame(cadre, fg_color="transparent")
                ligne.pack(fill="x", padx=8, pady=(18, 8))
                lab(ligne, texte, 16, "#FFFFFF", True, wrap=L - 40).pack(side="left")
                ctk.CTkFrame(ligne, height=2, fg_color="#22344A").pack(side="left", fill="x", expand=True, padx=(12, 0))
                self.notice_index[idx].append((None, texte.lower()))
            elif type_.startswith("h2"):
                fermer()
                teinte = type_[2:]
                fond, bord, coul = CARTES_NOTICE.get(teinte, CARTES_NOTICE["n"])
                cadre_carte = ctk.CTkFrame(cadre, fg_color=fond, border_width=1, border_color=bord, corner_radius=14)
                cadre_carte.pack(fill="x", padx=8, pady=(6, 10))
                carte = (cadre_carte, teinte, L - 44)
                lab(cadre_carte, texte, 13, coul, True).pack(anchor="w", padx=18, pady=(12, 6))
                self.notice_index[idx].append((cadre_carte, texte.lower()))
            else:
                coul_pt = CARTES_NOTICE[teinte][2] if teinte else "#EE5A24"
                if type_ == "p":
                    lab(parent(), texte, 12, "#C3D0DE").pack(anchor="w", padx=18 if carte else 8, pady=(2, 6))
                elif type_ in ("b", "step"):
                    ligne = ctk.CTkFrame(parent(), fg_color="transparent")
                    ligne.pack(fill="x", padx=(14 if carte else 4), pady=(2, 4))
                    if type_ == "step":
                        m = re.match(r"^(\d+\.)\s+(.*)$", texte)
                        marque, reste = (m.group(1), m.group(2)) if m else ("•", texte)
                    else:
                        marque, reste = "▸", texte
                    ctk.CTkLabel(ligne, text=marque, font=self._notice_police(16 if marque == "▸" else 12, True), text_color=coul_pt, width=26, anchor="n").pack(side="left", anchor="n", padx=(4, 4), pady=(0, 0))
                    col = ctk.CTkFrame(ligne, fg_color="transparent")
                    col.pack(side="left", fill="x", expand=True)
                    interieur = largeur_texte() - 50
                    intitule, corps = separer_intitule(reste)
                    if intitule:
                        lab(col, intitule, 12, "#FFFFFF", True, wrap=interieur).pack(anchor="w")
                        lab(col, corps, 12, "#C3D0DE", wrap=interieur).pack(anchor="w", pady=(0, 2))
                    else:
                        lab(col, reste, 12, "#C3D0DE", wrap=interieur).pack(anchor="w")
                    self.notice_index[idx].append((carte[0] if carte else None, texte.lower()))
                    continue
                elif type_ == "sub":
                    lab(parent(), "–  " + texte, 11, "#AFC0D2", wrap=largeur_texte() - 90).pack(anchor="w", padx=(64 if carte else 52, 14), pady=(0, 3))
                self.notice_index[idx].append((carte[0] if carte else None, texte.lower()))
        ctk.CTkFrame(cadre, height=18, fg_color="transparent").pack()

    def _notice_chercher(self, event=None):
        requete = self.notice_champ.get().strip().lower()
        if not requete:
            return
        try:
            idx = self.tab_names.index(self.notice_tabview.get()) + 1
        except Exception:
            return
        self._construire_vue_notice(idx)
        liste = [(w, t) for (w, t) in self.notice_index.get(idx, []) if w is not None]
        trouves = [i for i, (w, t) in enumerate(liste) if requete in t]
        if not trouves:
            self.notice_etat.configure(text=choisir(self.lang, "Aucun résultat", "No result", "Kein Treffer", "Sin resultados", "Nessun risultato"))
            self.after(2500, lambda: self.notice_etat.configure(text=""))
            return
        if requete != self.notice_derniere:
            self.notice_pos = -1
            self.notice_derniere = requete
        suivants = [i for i in trouves if i > self.notice_pos]
        choix = suivants[0] if suivants else trouves[0]
        self.notice_pos = choix
        widget = liste[choix][0]
        self.notice_etat.configure(text=f"{trouves.index(choix) + 1}/{len(trouves)}")
        try:
            sf = self.notice_vues[idx]
            sf.update_idletasks()
            y = widget.winfo_rooty() - sf.winfo_rooty()
            total = max(sf.winfo_height(), 1)
            sf._parent_canvas.yview_moveto(max(0.0, (y - 20) / total))
            ancien = widget.cget("border_color")
            widget.configure(border_color="#FFD166", border_width=3)
            self.after(1400, lambda: widget.configure(border_color=ancien, border_width=1))
        except Exception:
            pass

    def _msg(self, nom, *args, **kw):
        """Boîtes de dialogue rattachées à la notice : elles s'affichent au premier plan (la notice est « toujours au-dessus »)."""
        kw.setdefault("parent", self)
        return getattr(messagebox, nom)(*args, **kw)

    def obtenir_chemin_pdf_langue(self):
        # Notice_XX.pdf de la langue en cours (assets_arcade) : FR -> Notice_FR.pdf, EN -> Notice_EN.pdf, etc.
        nom_fichier = f"Notice_{self.lang.upper()}.pdf"
        pdf_path = get_resource_path(os.path.join("assets_arcade", nom_fichier))
        if not os.path.exists(pdf_path):
            pdf_path = os.path.join(get_assets_path(), nom_fichier)
        return pdf_path, nom_fichier

    @staticmethod
    def compter_pages_pdf(chemin):
        """Nombre de pages d'un PDF (lecture simple du fichier) ; None si impossible."""
        try:
            with open(chemin, "rb") as f:
                data = f.read()
            nombres = [int(x) for x in re.findall(rb"/Type\s*/Pages[^>]*?/Count\s+(\d+)", data)]
            nombres += [int(x) for x in re.findall(rb"/Count\s+(\d+)[^>]*?/Type\s*/Pages", data)]
            if nombres:
                return max(nombres)
            n = len(re.findall(rb"/Type\s*/Page[^s]", data))
            return n or None
        except Exception:
            return None

    def texte_infobulle_impression(self):
        pdf_path, _ = self.obtenir_chemin_pdf_langue()
        n = self.compter_pages_pdf(pdf_path) if os.path.exists(pdf_path) else None
        lg = self.lang
        if n:
            return choisir(lg, f"Imprimer toute la notice ({n} pages)", f"Print the whole manual ({n} pages)", f"Das gesamte Handbuch drucken ({n} Seiten)", f"Imprimir todo el manual ({n} páginas)", f"Stampa tutto il manuale ({n} pagine)")
        return choisir(lg, "Imprimer toute la notice", "Print the whole manual", "Das gesamte Handbuch drucken", "Imprimir todo el manual", "Stampa tutto il manuale")

    def imprimer_toute_notice(self):
        lg = self.lang
        pdf_path, nom = self.obtenir_chemin_pdf_langue()
        if not os.path.exists(pdf_path):
            self._msg("showerror", 
                choisir(lg, "Fichier introuvable", "File not found", "Datei nicht gefunden", "Archivo no encontrado", "File non trovato"),
                choisir(lg, f"{nom} est introuvable dans assets_arcade.", f"{nom} was not found in assets_arcade.", f"{nom} wurde in assets_arcade nicht gefunden.", f"No se ha encontrado {nom} en assets_arcade.", f"{nom} non è stato trovato in assets_arcade."))
            return
        if not self._msg("askyesno", 
                choisir(lg, "Impression", "Printing", "Drucken", "Impresión", "Stampa"),
                self.texte_infobulle_impression() + " ?"):
            return
        try:
            os.startfile(pdf_path, "print")
        except Exception:
            try:
                os.startfile(pdf_path)
                self._msg("showinfo", 
                    choisir(lg, "Impression", "Printing", "Drucken", "Impresión", "Stampa"),
                    choisir(lg, "La notice s'ouvre dans votre lecteur PDF : utilisez Ctrl + P pour l'imprimer.",
                            "The manual opens in your PDF reader: press Ctrl + P to print it.",
                            "Das Handbuch öffnet sich in Ihrem PDF-Programm: Drücken Sie Strg + P zum Drucken.",
                            "El manual se abre en su lector de PDF: pulse Ctrl + P para imprimirlo.",
                            "Il manuale si apre nel lettore PDF: premi Ctrl + P per stamparlo."))
            except Exception as e:
                self._msg("showerror", choisir(lg, "Erreur", "Error", "Fehler", "Error", "Errore"), str(e))

    def sauvegarder_pdf_langue(self):
        lg = self.lang
        try:
            pdf_path, nom_defaut = self.obtenir_chemin_pdf_langue()
            if not os.path.exists(pdf_path):
                self._msg("showerror", 
                    choisir(lg, "Fichier introuvable", "File not found", "Datei nicht gefunden", "Archivo no encontrado", "File non trovato"),
                    choisir(lg,
                            f"Le fichier PDF pour la langue '{lg.upper()}' est introuvable dans assets_arcade.",
                            f"The PDF file for language '{lg.upper()}' was not found in assets_arcade.",
                            f"Die PDF-Datei für die Sprache '{lg.upper()}' wurde in assets_arcade nicht gefunden.",
                            f"No se ha encontrado el archivo PDF del idioma '{lg.upper()}' en assets_arcade.",
                            f"Il file PDF per la lingua '{lg.upper()}' non è stato trovato in assets_arcade."))
                return

            dest_path = filedialog.asksaveasfilename(parent=self, 
                title=choisir(lg, "Enregistrer la notice PDF", "Save the PDF manual", "PDF-Handbuch speichern", "Guardar el manual PDF", "Salva il manuale PDF"),
                initialfile=nom_defaut,
                defaultextension=".pdf",
                filetypes=[(choisir(lg, "Fichiers PDF", "PDF files", "PDF-Dateien", "Archivos PDF", "File PDF"), "*.pdf"),
                           (choisir(lg, "Tous les fichiers", "All files", "Alle Dateien", "Todos los archivos", "Tutti i file"), "*.*")]
            )
            if dest_path:
                shutil.copy2(pdf_path, dest_path)
                msg = choisir(lg,
                              f"Notice PDF enregistrée avec succès sous :\n{dest_path}",
                              f"PDF successfully saved to:\n{dest_path}",
                              f"PDF erfolgreich gespeichert unter:\n{dest_path}",
                              f"Manual PDF guardado correctamente en:\n{dest_path}",
                              f"Manuale PDF salvato correttamente in:\n{dest_path}")
                self._msg("showinfo", choisir(lg, "Succès", "Success", "Erfolg", "Éxito", "Operazione riuscita"), msg)
        except Exception as e:
            err_msg = choisir(lg,
                              f"Impossible d'enregistrer le PDF :\n{e}",
                              f"Could not save PDF:\n{e}",
                              f"Das PDF konnte nicht gespeichert werden:\n{e}",
                              f"No se pudo guardar el PDF:\n{e}",
                              f"Impossibile salvare il PDF:\n{e}")
            self._msg("showerror", choisir(lg, "Erreur", "Error", "Fehler", "Error", "Errore"), err_msg)

    def imprimer_onglet_actif(self):
        lg = self.lang
        titre_erreur = choisir(lg, "Erreur", "Error", "Fehler", "Error", "Errore")
        try:
            onglet_courant = self.notice_tabview.get()
            index_onglet = self.tab_names.index(onglet_courant) + 1
            txt_box = getattr(self, f"txt_{index_onglet}", None)

            if not txt_box:
                self._msg("showerror", titre_erreur, choisir(
                    lg,
                    "Impossible de récupérer le contenu de l'onglet actif.",
                    "Could not retrieve the content of the active tab.",
                    "Der Inhalt des aktiven Tabs konnte nicht abgerufen werden.",
                    "No se pudo recuperar el contenido de la pestaña activa.",
                    "Impossibile recuperare il contenuto della scheda attiva."))
                return

            contenu_texte = txt_box.get("1.0", "end").strip()
            if not contenu_texte:
                self._msg("showwarning", 
                    choisir(lg, "Avertissement", "Warning", "Warnung", "Aviso", "Avviso"),
                    choisir(lg, "L'onglet actif est vide.", "The active tab is empty.", "Der aktive Tab ist leer.", "La pestaña activa está vacía.", "La scheda attiva è vuota."))
                return

            temp_txt_path = os.path.join(os.environ.get("TEMP", r"C:\Windows\Temp"), f"Notice_Atelier_{index_onglet}.txt")
            titre_fichier = choisir(lg, "NOTICE TECHNIQUE", "TECHNICAL MANUAL", "TECHNISCHES HANDBUCH", "MANUAL TÉCNICO", "MANUALE TECNICO")
            with open(temp_txt_path, "w", encoding="utf-8") as f:
                f.write(f"=== ATELIER PC BOOSTER PRO — {titre_fichier} ({onglet_courant.upper()}) ===\n\n")
                f.write(contenu_texte)

            os.startfile(temp_txt_path, "print")

            msg = choisir(lg,
                          f"Impression lancée pour l'onglet : {onglet_courant}",
                          f"Print job sent for tab: {onglet_courant}",
                          f"Druckauftrag für den Tab gesendet: {onglet_courant}",
                          f"Impresión enviada para la pestaña: {onglet_courant}",
                          f"Stampa avviata per la scheda: {onglet_courant}")
            self._msg("showinfo", choisir(lg, "Impression", "Printing", "Drucken", "Impresión", "Stampa"), msg)
        except Exception as e:
            err_msg = choisir(lg,
                              f"Impossible d'imprimer l'onglet actif :\n{e}",
                              f"Could not print active tab:\n{e}",
                              f"Der aktive Tab konnte nicht gedruckt werden:\n{e}",
                              f"No se pudo imprimir la pestaña activa:\n{e}",
                              f"Impossibile stampare la scheda attiva:\n{e}")
            self._msg("showerror", titre_erreur, err_msg)

