def appliquer_jetons(script, lb):
    """Remplace dans un script PowerShell les jetons @@...@@ par les textes de la langue active."""
    def ligne(cle):  # libellé de ligne aligné sur 12 caractères
        return f"{lb[cle]:<12}"
    jetons = {
        "@@R_SYSTEM@@": ligne("r_system"), "@@R_MODEL@@": ligne("r_model"), "@@R_CORES@@": ligne("r_cores"),
        "@@R_MAKER@@": ligne("r_maker"), "@@R_REVISION@@": ligne("r_revision"),
        "@@R_CAPACITY@@": ligne("r_capacity"), "@@R_FREQ@@": ligne("r_freq"),
        "@@GB@@": lb["gb"], "@@UNKNOWN@@": lb["unknown"], "@@POWER_DEFAULT@@": lb["power_default"],
        "@@BATT_NA@@": lb["batt_na"], "@@ST1@@": lb["st1"], "@@ST2@@": lb["st2"], "@@ST3@@": lb["st3"],
        "@@ST4@@": lb["st4"], "@@ST5@@": lb["st5"], "@@WEAR@@": lb["wear"],
        "@@DISK_UNKNOWN@@": lb["disk_unknown"], "@@DISK_PREFIX@@": lb["disk_prefix"],
        "@@LETTERS_NONE@@": lb["letters_none"], "@@HEALTHY@@": lb["healthy"],
        "@@HEALTHY_AUDIT@@": lb["healthy_audit"],
    }
    for jeton, valeur in jetons.items():
        script = script.replace(jeton, valeur)
    return script


