WINGET_CODES_OK = {0x8A15002B, 0x8A150061, 0x8A15010D, 0x8A15010E}   # déjà installé / rien à mettre à jour
WINGET_CODES_REDEMARRAGE = {0x8A150109, 0x8A15010B, 3010, 1641}


def decoder_code_winget(code, tr, nom, winget_id=""):
    """Code de retour de winget -> (symbole, message lisible). Le code brut est gardé entre parenthèses."""
    c = code & 0xFFFFFFFF
    hexa = f"0x{c:08X}"
    if c == 0:
        return "✔", tr(f"{nom} : installé.", f"{nom}: installed.", f"{nom}: installiert.", f"{nom}: instalado.", f"{nom}: installato.")
    if c in WINGET_CODES_OK:
        return "✔", tr(f"{nom} : déjà installé (rien à faire).", f"{nom}: already installed (nothing to do).",
                       f"{nom}: bereits installiert (nichts zu tun).", f"{nom}: ya instalado (nada que hacer).",
                       f"{nom}: già installato (niente da fare).")
    if c in WINGET_CODES_REDEMARRAGE:
        return "⚠", tr(f"{nom} : installé, un redémarrage du PC est nécessaire pour terminer.",
                       f"{nom}: installed, a restart is needed to finish.",
                       f"{nom}: installiert, zum Abschluss ist ein Neustart nötig.",
                       f"{nom}: instalado, hace falta reiniciar el PC para terminar.",
                       f"{nom}: installato, serve un riavvio del PC per completare.")
    if c == 0x8A150014:
        return "❌", tr(f"{nom} : introuvable dans le catalogue winget (identifiant « {winget_id} »).",
                        f"{nom}: not found in the winget catalogue (id \"{winget_id}\").",
                        f"{nom}: im winget-Katalog nicht gefunden (ID „{winget_id}“).",
                        f"{nom}: no se encuentra en el catálogo de winget (id «{winget_id}»).",
                        f"{nom}: non trovato nel catalogo winget (id «{winget_id}»).")
    if c == 0x8A150019:
        return "❌", tr(f"{nom} : droits administrateur requis. Relancez le logiciel en administrateur.",
                        f"{nom}: administrator rights required. Restart the software as administrator.",
                        f"{nom}: Administratorrechte erforderlich. Starten Sie das Programm als Administrator neu.",
                        f"{nom}: se requieren derechos de administrador. Reinicie el programa como administrador.",
                        f"{nom}: servono i diritti di amministratore. Riavvia il programma come amministratore.")
    if c == 0x8A150010:
        return "❌", tr(f"{nom} : aucun installeur compatible avec ce PC.", f"{nom}: no installer compatible with this PC.",
                        f"{nom}: kein mit diesem PC kompatibles Installationsprogramm.", f"{nom}: ningún instalador compatible con este PC.",
                        f"{nom}: nessun programma di installazione compatibile con questo PC.")
    if c == 0x8A150011:
        return "❌", tr(f"{nom} : fichier téléchargé corrompu (empreinte invalide). Réessayez.", f"{nom}: downloaded file corrupted (invalid hash). Try again.",
                        f"{nom}: heruntergeladene Datei beschädigt (ungültiger Hash). Erneut versuchen.", f"{nom}: archivo descargado dañado (hash no válido). Inténtelo de nuevo.",
                        f"{nom}: file scaricato danneggiato (hash non valido). Riprova.")
    if c == 0x8A15010C:
        return "⚠", tr(f"{nom} : installation annulée.", f"{nom}: installation cancelled.", f"{nom}: Installation abgebrochen.",
                        f"{nom}: instalación cancelada.", f"{nom}: installazione annullata.")
    return "⚠", tr(f"{nom} : l'installation n'a pas abouti (code {hexa}).", f"{nom}: the installation did not complete (code {hexa}).",
                   f"{nom}: Installation nicht abgeschlossen (Code {hexa}).", f"{nom}: la instalación no se completó (código {hexa}).",
                   f"{nom}: installazione non completata (codice {hexa}).")


