CREATE_NO_WINDOW = 0x08000000

# Référence vers la fenêtre principale de l'application, posée une seule fois au démarrage
# (voir l'appel à definir_fenetre_principale(self) dans AtelierBoosterApp.init_app). Sert à
# superposer la console SFC/DISM/etc. exactement par-dessus la fenêtre principale.
_fenetre_principale_ref = None


def definir_fenetre_principale(fenetre):
    global _fenetre_principale_ref
    _fenetre_principale_ref = fenetre


# Taille de la console par rapport à la fenêtre principale : on ne la recouvre pas entièrement,
# pour que les onglets (en haut) et la barre d'avancement / le statut (en bas) restent visibles.
CONSOLE_RATIO_LARGEUR = 0.75
CONSOLE_RATIO_HAUTEUR = 0.60
CONSOLE_LARGEUR_MIN = 560
CONSOLE_HAUTEUR_MIN = 360


def _positionner_fenetre_console(titre, essais=40, delai=0.1):
    """Cherche la fenêtre console nouvellement ouverte par son titre (via le titre passé à "start",
    qui devient le titre de la fenêtre) et la positionne/dimensionne pour qu'elle apparaisse CENTRÉE
    par-dessus la fenêtre principale, mais en plus petit (voir CONSOLE_RATIO_*) — pour laisser visibles
    les onglets en haut et la barre d'avancement/le statut en bas de l'application pendant que la
    commande tourne. Tourne dans un thread à part pour ne pas bloquer l'attente de la commande
    elle-même ; abandonne sans rien casser si la fenêtre principale n'est pas connue ou si la fenêtre
    console n'apparaît pas assez vite."""
    if _fenetre_principale_ref is None:
        return
    try:
        x_app = _fenetre_principale_ref.winfo_x()
        y_app = _fenetre_principale_ref.winfo_y()
        largeur_app = _fenetre_principale_ref.winfo_width()
        hauteur_app = _fenetre_principale_ref.winfo_height()
    except Exception:
        return
    largeur = max(CONSOLE_LARGEUR_MIN, int(largeur_app * CONSOLE_RATIO_LARGEUR))
    hauteur = max(CONSOLE_HAUTEUR_MIN, int(hauteur_app * CONSOLE_RATIO_HAUTEUR))
    largeur = min(largeur, largeur_app)  # ne jamais dépasser la fenêtre principale elle-même
    hauteur = min(hauteur, hauteur_app)
    x = x_app + (largeur_app - largeur) // 2
    y = y_app + (hauteur_app - hauteur) // 2
    user32 = ctypes.windll.user32
    hwnd = 0
    for _ in range(essais):
        hwnd = user32.FindWindowW(None, titre)
        if hwnd:
            break
        time.sleep(delai)
    if not hwnd:
        return
    try:
        # SWP_NOZORDER (0x0004) : on ne force pas la console au premier plan en continu,
        # on se contente de la centrer, en plus petit, par-dessus la fenêtre principale.
        user32.SetWindowPos(hwnd, 0, x, y, largeur, hauteur, 0x0004)
    except Exception:
        pass


def executer_commande_visible(commande, titre=""):
    """Lance une commande Windows dans une VRAIE fenêtre de console visible, qui hérite des droits
    administrateur du processus parent (déjà élevé au démarrage) — donc aucune nouvelle demande UAC.
    Utile pour les commandes longues et sans heurt visuel autrement (SFC /scannow, DISM /RestoreHealth) :
    l'utilisateur voit la progression native (le %) se dérouler en direct, au lieu d'un journal figé
    pendant potentiellement plusieurs dizaines de minutes. La fenêtre se ferme toute seule dès que la
    commande est terminée ; l'appel reste bloquant comme avant (la tâche de fond attend la fin).
    Elle est aussi automatiquement calée (position + taille) par-dessus la fenêtre principale.

    Important : on NE demande PAS nous-mêmes une nouvelle console via creationflags=CREATE_NEW_CONSOLE.
    Dans un exe compilé en --noconsole et déjà relancé en élevé (ShellExecuteW "runas") au démarrage,
    les handles standard hérités du processus parent sont parfois invalides ; Windows refuse alors en
    silence de créer la nouvelle console pour le process enfant (aucune fenêtre n'apparaît, et comme
    l'exception est absorbée, on bascule sans bruit sur le repli caché). On délègue donc la création de
    la fenêtre à la commande "start" du shell elle-même (via /wait, pour rester bloquant) : c'est elle qui
    alloue la nouvelle console, indépendamment des handles du processus Python — ça fonctionne de façon
    fiable même dans ce cas précis."""
    titre_securise = (titre or "Atelier PC Booster Pro").replace('"', "'")
    try:
        commande_demarrage = f'start "{titre_securise}" /wait cmd /c "{commande}"'
        # Thread à part : cherche la fenêtre console dès qu'elle apparaît et la cale sur la
        # fenêtre principale, pendant que l'appel bloquant ci-dessous attend la fin de la commande.
        threading.Thread(target=_positionner_fenetre_console, args=(titre_securise,), daemon=True).start()
        subprocess.run(commande_demarrage, shell=True, creationflags=CREATE_NO_WINDOW)
    except Exception:
        # Repli silencieux si même "start" échoue pour une raison quelconque
        # (par exemple un environnement très restreint) : on garde l'ancien comportement.
        subprocess.run(commande, shell=True, capture_output=True, creationflags=CREATE_NO_WINDOW)


