def executer_powershell(script, timeout=180):
    """Exécute un script PowerShell (encodé, sans fenêtre). Renvoie (code, sortie texte)."""
    try:
        entete = "[Console]::OutputEncoding=[Text.Encoding]::UTF8;$ProgressPreference='SilentlyContinue';"
        enc = _b64.b64encode((entete + script).encode("utf-16-le")).decode("ascii")
        r = subprocess.run(
            ["powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-EncodedCommand", enc],
            capture_output=True, text=True, encoding="utf-8", errors="ignore",
            timeout=timeout, creationflags=CREATE_NO_WINDOW,
        )
        return r.returncode, (r.stdout or "")
    except subprocess.TimeoutExpired:
        return -2, "TIMEOUT"
    except Exception as e:
        return -1, "ERR " + str(e)


# ---------- DNS : mesure de rapidité (requêtes UDP directes, sans outil externe) ----------
def construire_requete_dns(domaine, ident=None):
    ident = _random.randint(0, 65535) if ident is None else ident
    entete = _struct.pack(">HHHHHH", ident, 0x0100, 1, 0, 0, 0)
    question = b"".join(bytes([len(p)]) + p.encode("ascii") for p in domaine.strip(".").split(".")) + b"\x00"
    return ident, entete + question + _struct.pack(">HH", 1, 1)


def mesurer_dns(serveur, domaines, essais=2, delai=1.5, port=53):
    """Temps médian de réponse (ms) d'un serveur DNS, ou None s'il ne répond pas."""
    temps = []
    for _ in range(essais):
        for domaine in domaines:
            ident, requete = construire_requete_dns(domaine)
            s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
            s.settimeout(delai)
            try:
                t0 = time.perf_counter()
                s.sendto(requete, (serveur, port))
                data, _ = s.recvfrom(2048)
                dt = (time.perf_counter() - t0) * 1000.0
                if len(data) >= 12 and _struct.unpack(">H", data[:2])[0] == ident and (data[3] & 0x0F) == 0:
                    temps.append(dt)
            except Exception:
                pass
            finally:
                s.close()
    return _stats.median(temps) if temps else None


