def ps_appliquer_dns(v4, v6):
    """Script PowerShell : applique DNS IPv4 + IPv6 sur chaque carte physique active, puis vérifie."""
    def liste(l):
        return "@(" + ",".join("'" + x + "'" for x in l) + ")"
    return r"""
$v4=%s; $v6=%s; $all=@($v4)+@($v6)
$ads=@(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' })
if(-not $ads.Count){ $ads=@(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and -not $_.Virtual }) }
foreach($a in $ads){
  $n=$a.Name; $i=$a.ifIndex; $info=@()
  if($v6.Count){
    $b=Get-NetAdapterBinding -Name $n -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue
    if($b -and -not $b.Enabled){
      try{ Enable-NetAdapterBinding -Name $n -ComponentID ms_tcpip6 -ErrorAction Stop; $info+='BINDING_ON'; Start-Sleep -Seconds 3 }catch{ $info+='BINDING_FAIL' }
    }
  }
  try{ Set-DnsClientServerAddress -InterfaceIndex $i -ServerAddresses $all -ErrorAction Stop }catch{ $info+=('SET_FAIL:'+$_.Exception.Message) }
  $r4=@((Get-DnsClientServerAddress -InterfaceIndex $i -AddressFamily IPv4 -ErrorAction SilentlyContinue).ServerAddresses)
  $r6=@((Get-DnsClientServerAddress -InterfaceIndex $i -AddressFamily IPv6 -ErrorAction SilentlyContinue).ServerAddresses)
  if($v6.Count -and (@($v6 | Where-Object { $r6 -notcontains $_ }).Count -gt 0)){
    try{
      netsh interface ipv6 set dnsservers name="$n" source=static address=$($v6[0]) validate=no | Out-Null
      for($k=1;$k -lt $v6.Count;$k++){ netsh interface ipv6 add dnsservers name="$n" address=$($v6[$k]) index=$($k+1) validate=no | Out-Null }
      $info+='NETSH'
    }catch{ $info+='NETSH_FAIL' }
    $r6=@((Get-DnsClientServerAddress -InterfaceIndex $i -AddressFamily IPv6 -ErrorAction SilentlyContinue).ServerAddresses)
  }
  $ok4=(@($v4 | Where-Object { $r4 -notcontains $_ }).Count -eq 0)
  $ok6=(@($v6 | Where-Object { $r6 -notcontains $_ }).Count -eq 0)
  "RES|$n|$ok4|$ok6|$($r6 -join ',')|$($info -join ';')"
}
$dc=(Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters' -ErrorAction SilentlyContinue).DisabledComponents
"DC|$dc"
""" % (liste(v4), liste(v6))


def analyser_resultat_dns(sortie, tr, avec_v6=True):
    """Transforme la sortie du script en lignes (niveau, texte) pour le journal. Renvoie (lignes, tout_ok)."""
    lignes, tout_ok, vu = [], True, False
    for brut in (sortie or "").splitlines():
        parts = brut.strip().split("|")
        if parts[0] == "RES" and len(parts) >= 6:
            vu = True
            nom, ok4, ok6, r6, info = parts[1], parts[2] == "True", parts[3] == "True", parts[4], parts[5]
            lignes.append(("ok" if ok4 else "bad", tr(f"{nom} : IPv4 {'OK' if ok4 else 'ÉCHEC'}", f"{nom}: IPv4 {'OK' if ok4 else 'FAILED'}", f"{nom}: IPv4 {'OK' if ok4 else 'FEHLER'}", f"{nom}: IPv4 {'OK' if ok4 else 'FALLO'}", f"{nom}: IPv4 {'OK' if ok4 else 'ERRORE'}")))
            if avec_v6:
                lignes.append(("ok" if ok6 else "bad", tr(f"{nom} : IPv6 {'OK' if ok6 else 'ÉCHEC'} {('(' + r6 + ')') if r6 else ''}", f"{nom}: IPv6 {'OK' if ok6 else 'FAILED'} {('(' + r6 + ')') if r6 else ''}", f"{nom}: IPv6 {'OK' if ok6 else 'FEHLER'} {('(' + r6 + ')') if r6 else ''}", f"{nom}: IPv6 {'OK' if ok6 else 'FALLO'} {('(' + r6 + ')') if r6 else ''}", f"{nom}: IPv6 {'OK' if ok6 else 'ERRORE'} {('(' + r6 + ')') if r6 else ''}")))
            if "BINDING_ON" in info:
                lignes.append(("info", tr("   ↳ Le protocole IPv6 était désactivé sur cette carte : il a été réactivé.", "   ↳ IPv6 was disabled on this adapter: it has been re-enabled.", "   ↳ IPv6 war auf diesem Adapter deaktiviert: wurde wieder aktiviert.", "   ↳ IPv6 estaba desactivado en esta tarjeta: se ha reactivado.", "   ↳ IPv6 era disattivato su questa scheda: è stato riattivato.")))
            if "BINDING_FAIL" in info:
                lignes.append(("warn", tr("   ↳ Impossible de réactiver IPv6 sur cette carte (verrouillé par le pilote ou une stratégie).", "   ↳ Could not re-enable IPv6 on this adapter (locked by driver or policy).", "   ↳ IPv6 konnte nicht reaktiviert werden (durch Treiber oder Richtlinie gesperrt).", "   ↳ No se pudo reactivar IPv6 (bloqueado por el controlador o una directiva).", "   ↳ Impossibile riattivare IPv6 (bloccato da driver o criterio).")))
            if "NETSH" in info:
                lignes.append(("info", tr("   ↳ Méthode de secours (netsh) utilisée pour IPv6.", "   ↳ Fallback method (netsh) used for IPv6.", "   ↳ Ersatzmethode (netsh) für IPv6 verwendet.", "   ↳ Se usó el método alternativo (netsh) para IPv6.", "   ↳ Usato il metodo alternativo (netsh) per IPv6.")))
            for x in info.split(";"):
                if x.startswith("SET_FAIL:"):
                    lignes.append(("warn", "   ↳ " + x[9:][:160]))
            if not ok4 or (avec_v6 and not ok6):
                tout_ok = False
        elif parts[0] == "DC" and avec_v6:
            val = parts[1].strip() if len(parts) > 1 else ""
            if val.isdigit() and (int(val) & 0x01 or int(val) == 0xFF):
                lignes.append(("bad", tr("IPv6 est désactivé globalement dans le registre Windows (DisabledComponents = %s). Une personne l'a bloqué volontairement : voir la valeur à remettre à 0.", "IPv6 is globally disabled in the Windows registry (DisabledComponents = %s). Someone blocked it on purpose: set it back to 0.", "IPv6 ist in der Windows-Registry global deaktiviert (DisabledComponents = %s). Setzen Sie den Wert auf 0 zurück.", "IPv6 está desactivado globalmente en el registro de Windows (DisabledComponents = %s). Vuelva a poner el valor en 0.", "IPv6 è disattivato globalmente nel registro di Windows (DisabledComponents = %s). Riporta il valore a 0.") % val))
                tout_ok = False
    if not vu:
        lignes.append(("bad", tr("Aucune carte réseau active trouvée.", "No active network adapter found.", "Kein aktiver Netzwerkadapter gefunden.", "No se encontró ninguna tarjeta de red activa.", "Nessuna scheda di rete attiva trovata.")))
        tout_ok = False
    return lignes, tout_ok


