def _liste_ips(texte):
    return [x for x in re.split(r"[,\s;]+", (texte or "").strip()) if x]


def analyser_etat_dns(sortie):
    """Sortie de PS_DNS_ETAT -> liste de cartes {nom, eff4, eff6, stat4, stat6}."""
    cartes = []
    for brut in (sortie or "").splitlines():
        p = brut.rstrip("\r\n").split("|")
        if p and p[0] == "ETAT" and len(p) >= 6:
            cartes.append({"nom": p[1], "eff4": _liste_ips(p[2]), "eff6": _liste_ips(p[3]),
                           "stat4": _liste_ips(p[4]), "stat6": _liste_ips(p[5])})
    return cartes


def identifier_profil_dns(carte, profils):
    """profils = {id: {'type','ipv4','ipv6'}}. Renvoie l'id reconnu, 'dhcp', ou None (réglage personnalisé)."""
    if not carte["stat4"] and not carte["stat6"]:
        return "dhcp"
    a4 = [x.lower() for x in (carte["stat4"] or carte["eff4"])]
    for pid, prof in profils.items():
        if prof.get("type") == "static" and [x.lower() for x in prof.get("ipv4", [])] == a4:
            return pid
    return None


def ps_restaurer_dns(sauvegarde):
    """Remet chaque carte dans son état sauvegardé (automatique ou adresses fixes d'avant)."""
    def q(x):
        return "'" + x.replace("'", "''") + "'"
    blocs = []
    for c in sauvegarde:
        fixes = list(c.get("stat4", [])) + list(c.get("stat6", []))
        n = q(c["nom"])
        t = "$a=Get-NetAdapter -Name %s -ErrorAction SilentlyContinue\nif($a){ try{\n" % n
        t += "Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ResetServerAddresses -ErrorAction Stop\n"
        if fixes:
            t += "Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses @(%s) -ErrorAction Stop\n" % ",".join(q(x) for x in fixes)
        t += "'REST|' + %s + '|OK' }catch{ 'REST|' + %s + '|FAIL' } } else { 'REST|' + %s + '|ABSENT' }" % (n, n, n)
        blocs.append(t)
    return "\n".join(blocs)


def decider_reparation(e):
    """e : {'ip': bool, 'gw': str|None, 'ping_gw': bool, 'ping_net': bool, 'dns_ok': bool}
    -> (cause, actions) ; cause ∈ pas_ip | box | fai | dns | sain."""
    if not e.get("ip"):
        return "pas_ip", ["restart_adapter", "renew"]
    if e.get("ping_net"):
        return ("sain", []) if e.get("dns_ok") else ("dns", ["flush", "cloudflare"])
    if e.get("gw") and e.get("ping_gw"):
        return "fai", []
    return "box", ["restart_adapter", "renew"]


def ping_ok(hote, essais=2, delai_ms=1500):
    """True si l'hôte répond au ping (détection sur « TTL= », indépendante de la langue)."""
    try:
        r = subprocess.run(["ping", "-n", str(essais), "-w", str(delai_ms), hote], capture_output=True, text=True,
                           encoding="cp850", errors="ignore", creationflags=CREATE_NO_WINDOW, timeout=essais * 4 + 5)
        return "TTL=" in (r.stdout or "").upper()
    except Exception:
        return False


def dns_resout(nom="www.microsoft.com"):
    try:
        _socket.getaddrinfo(nom, 443)
        return True
    except Exception:
        return False


