    def _dp_dossier_puis_lancer(self, quoi):
        """Choisit le dossier dans le fil principal (Tkinter), puis lance le travail en arriere-plan."""
        tr = self.tr
        if quoi == "import":
            if not self._dp_avertir_si_pas_admin():
                return
            titre = tr("Dossier contenant les pilotes à réinstaller", "Folder containing the drivers to reinstall",
                       "Ordner mit den neu zu installierenden Treibern", "Carpeta con los controladores a reinstalar",
                       "Cartella con i driver da reinstallare")
            fonction, bouton = self._dp_import_pilotes, self.btn_dp_import
        else:
            titre = tr("Dossier où exporter les pilotes", "Folder to export drivers to", "Ordner für den Treiberexport",
                       "Carpeta donde exportar los controladores", "Cartella in cui esportare i driver")
            fonction, bouton = self._dp_export_pilotes, self.btn_dp_drv
        dossier = filedialog.askdirectory(parent=self, title=titre)
        if dossier:
            self.dp_lancer(lambda: fonction(dossier), bouton)

    def _dp_basculer_section(self, idx):
        """Accordeon : ouvre la section cliquee et referme les autres (une seule ouverte)."""
        for i, sec in enumerate(getattr(self, "_dp_sections", [])):
            ouvrir = (i == idx) and (not sec["ouvert"])
            sec["ouvert"] = ouvrir
            if ouvrir:
                sec["entete"].configure(text="▾  " + sec["titre"])
                sec["corps"].pack(fill="x", padx=6, pady=(0, 6))
            else:
                sec["entete"].configure(text="▸  " + sec["titre"])
                sec["corps"].pack_forget()

    def _dp_import_pilotes(self, dossier=None):
        tr = self.tr
        if not self._dp_avertir_si_pas_admin():
            return
        if dossier is None:
            dossier = filedialog.askdirectory(parent=self, title=tr(
            "Dossier contenant les pilotes à réinstaller", "Folder containing the drivers to reinstall",
            "Ordner mit den neu zu installierenden Treibern", "Carpeta con los controladores a reinstalar",
            "Cartella con i driver da reinstallare"))
        if not dossier:
            return
        self.dp_ecrire("⏳ " + tr("Réinstallation des pilotes depuis le dossier (peut prendre un moment)...",
                                      "Reinstalling drivers from the folder (may take a while)...",
                                      "Treiber werden aus dem Ordner neu installiert (kann dauern)...",
                                      "Reinstalando los controladores desde la carpeta (puede tardar)...",
                                      "Reinstallazione dei driver dalla cartella (può richiedere tempo)..."), effacer=True)
        chemin_inf = os.path.join(dossier, "*.inf")
        try:
            r = subprocess.run('pnputil /add-driver "' + chemin_inf + '" /subdirs /install',
                               shell=True, capture_output=True, text=True, encoding=page_oem(), errors="ignore", creationflags=CREATE_NO_WINDOW)
            sortie = (r.stdout or "") + (r.stderr or "")
        except Exception as e:
            self.dp_ecrire("❌ " + str(e))
            return
        bas = sortie.lower()
        if "accès refusé" in bas or "access is denied" in bas or "zugriff verweigert" in bas or "acceso denegado" in bas or "accesso negato" in bas:
            self.dp_ecrire(tr(
                "❌ Accès refusé. Relancez le logiciel avec «\u00a0Exécuter en tant qu'administrateur\u00a0», puis réessayez.",
                "❌ Access denied. Restart the software with “Run as administrator”, then try again.",
                "❌ Zugriff verweigert. Starten Sie das Programm über „Als Administrator ausführen“ und versuchen Sie es erneut.",
                "❌ Acceso denegado. Reinicie el programa con «Ejecutar como administrador» e inténtelo de nuevo.",
                "❌ Accesso negato. Riavvia il programma con «Esegui come amministratore» e riprova."), effacer=True)
            return
        nb = len(re.findall(r"\.inf", sortie, re.IGNORECASE))
        self.dp_ecrire("=== " + tr("IMPORT DES PILOTES", "DRIVER IMPORT", "TREIBERIMPORT", "IMPORTACIÓN DE CONTROLADORES", "IMPORTAZIONE DEI DRIVER") + " ===", effacer=True)
        self.dp_ecrire("")
        if r.returncode == 0:
            self.dp_ecrire("✔ " + tr("Pilotes réinstallés depuis : ", "Drivers reinstalled from: ", "Treiber neu installiert aus: ", "Controladores reinstalados desde: ", "Driver reinstallati da: ") + dossier)
        else:
            self.dp_ecrire("⚠ " + tr("Import terminé avec des avertissements (détail ci-dessous).",
                                          "Import finished with warnings (details below).",
                                          "Import mit Warnungen abgeschlossen (Details unten).",
                                          "Importación terminada con advertencias (detalles abajo).",
                                          "Importazione terminata con avvisi (dettagli sotto)."))
        if nb:
            self.dp_ecrire("   " + tr(str(nb) + " paquet(s) .inf traité(s).", str(nb) + " .inf package(s) processed.",
                                      str(nb) + " .inf-Paket(e) verarbeitet.", str(nb) + " paquete(s) .inf procesado(s).",
                                      str(nb) + " pacchetto/i .inf elaborato/i."))
        else:
            self.dp_ecrire("ℹ\ufe0f " + tr("Aucun fichier .inf trouvé dans ce dossier (ni ses sous-dossiers).",
                                                "No .inf file found in this folder (or its subfolders).",
                                                "Keine .inf-Datei in diesem Ordner (oder Unterordnern) gefunden.",
                                                "No se encontró ningún archivo .inf en esta carpeta (ni subcarpetas).",
                                                "Nessun file .inf trovato in questa cartella (o sottocartelle)."))
        self.dp_ecrire("")
        self.dp_ecrire("🔁 " + tr("Redémarrez le PC pour finaliser l'installation des pilotes.",
                                          "Restart the PC to finish installing the drivers.",
                                          "Starten Sie den PC neu, um die Treiberinstallation abzuschließen.",
                                          "Reinicie el PC para finalizar la instalación de los controladores.",
                                          "Riavvia il PC per completare l'installazione dei driver."))
        if sortie.strip():
            self.dp_ecrire("")
            self.dp_ecrire(sortie.strip())
        self.noter_action(tr("Pilotes réimportés", "Drivers reimported", "Treiber reimportiert", "Controladores reimportados", "Driver reimportati"), dossier)

    def _dp_sante(self):
        tr = self.tr
        self.dp_ecrire(tr("⏳ Analyse de la santé de Windows (la recherche de mises à jour peut durer une minute)...",
                          "⏳ Checking Windows health (the update search can take a minute)...",
                          "⏳ Windows-Zustand wird geprüft (die Update-Suche kann eine Minute dauern)...",
                          "⏳ Comprobando el estado de Windows (la búsqueda de actualizaciones puede tardar un minuto)...",
                          "⏳ Controllo dello stato di Windows (la ricerca degli aggiornamenti può richiedere un minuto)..."), effacer=True)
        code, sortie = executer_powershell(PS_SANTE, 300)
        try:
            lecteur = os.environ.get("SystemDrive", "C:") + "\\"
            total, _, libre = shutil.disk_usage(lecteur)
            pct = libre * 100.0 / total
        except Exception:
            pct = None
        lignes = analyser_sante(sortie, tr, pct)
        self.rapport_data["sante"] = lignes
        self.dp_ecrire("=== " + tr("SANTÉ DE WINDOWS", "WINDOWS HEALTH", "WINDOWS-ZUSTAND", "ESTADO DE WINDOWS", "STATO DI WINDOWS") + " ===", effacer=True)
        self.dp_ecrire("")
        self.dp_ecrire_lignes(lignes)
        nb_bad = len([1 for n, _ in lignes if n == "bad"])
        nb_warn = len([1 for n, _ in lignes if n == "warn"])
        self.noter_action(tr("Contrôle de la santé de Windows", "Windows health check", "Prüfung des Windows-Zustands", "Revisión del estado de Windows", "Controllo dello stato di Windows"),
                          tr(f"{nb_bad} problème(s), {nb_warn} avertissement(s)", f"{nb_bad} problem(s), {nb_warn} warning(s)", f"{nb_bad} Problem(e), {nb_warn} Warnung(en)", f"{nb_bad} problema(s), {nb_warn} advertencia(s)", f"{nb_bad} problema/i, {nb_warn} avviso/i"))

    def _dp_plantages(self):
        tr = self.tr
        self.dp_ecrire(tr("⏳ Lecture du journal d'événements Windows (30 derniers jours)...", "⏳ Reading the Windows event log (last 30 days)...",
                          "⏳ Windows-Ereignisprotokoll wird gelesen (letzte 30 Tage)...", "⏳ Leyendo el registro de eventos de Windows (últimos 30 días)...",
                          "⏳ Lettura del registro eventi di Windows (ultimi 30 giorni)..."), effacer=True)
        code, sortie = executer_powershell(PS_PLANTAGES, 240)
        dumps = None
        try:
            fichiers = _glob.glob(os.path.join(os.environ.get("SystemRoot", r"C:\Windows"), "Minidump", "*.dmp"))
            if fichiers:
                recent = max(fichiers, key=os.path.getmtime)
                dumps = (len(fichiers), time.strftime("%Y-%m-%d %H:%M", time.localtime(os.path.getmtime(recent))))
        except Exception:
            pass
        lignes = analyser_plantages(sortie, tr, dumps)
        self.rapport_data["plantages"] = lignes
        self.dp_ecrire("=== " + tr("ANALYSE DES PLANTAGES (30 JOURS)", "CRASH ANALYSIS (30 DAYS)", "ABSTURZANALYSE (30 TAGE)", "ANÁLISIS DE FALLOS (30 DÍAS)", "ANALISI DEI CRASH (30 GIORNI)") + " ===", effacer=True)
        self.dp_ecrire("")
        self.dp_ecrire_lignes(lignes)
        self.noter_action(tr("Analyse des plantages", "Crash analysis", "Absturzanalyse", "Análisis de fallos", "Analisi dei crash"))

    def dp_memoire(self):
        tr = self.tr
        if not messagebox.askyesno(
                tr("Test mémoire", "Memory test", "Speichertest", "Prueba de memoria", "Test memoria"),
                tr("Windows va proposer de redémarrer le PC pour tester la mémoire (10 à 30 minutes).\n\nEnregistrez vos travaux puis continuez.\n\nLancer l'outil ?",
                   "Windows will offer to restart the PC to test the memory (10 to 30 minutes).\n\nSave your work, then continue.\n\nStart the tool?",
                   "Windows bietet an, den PC zum Speichertest neu zu starten (10 bis 30 Minuten).\n\nSpeichern Sie Ihre Arbeit und fahren Sie fort.\n\nWerkzeug starten?",
                   "Windows propondrá reiniciar el PC para probar la memoria (10 a 30 minutos).\n\nGuarde su trabajo y continúe.\n\n¿Iniciar la herramienta?",
                   "Windows proporrà di riavviare il PC per testare la memoria (da 10 a 30 minuti).\n\nSalva il lavoro e prosegui.\n\nAvviare lo strumento?")):
            return
        try:
            subprocess.Popen("mdsched.exe", shell=True)
            self.noter_action(tr("Test mémoire Windows lancé", "Windows memory test started", "Windows-Speichertest gestartet", "Prueba de memoria de Windows iniciada", "Test memoria di Windows avviato"))
        except Exception as e:
            messagebox.showerror(tr("Erreur", "Error", "Fehler", "Error", "Errore"), str(e))

    def _dp_avertir_si_pas_admin(self):
        """CHKDSK (et d'autres outils système) exigent les droits administrateur. Message clair au lieu du brut 'Accès refusé'."""
        if is_admin():
            return True
        tr = self.tr
        self.dp_ecrire(tr(
            "❌ Droits administrateur requis : fermez le logiciel et relancez-le avec « Exécuter en tant qu'administrateur » (clic droit sur l'icône), puis réessayez.",
            "❌ Administrator rights required: close the software and start it again with “Run as administrator” (right-click the icon), then try again.",
            "❌ Administratorrechte erforderlich: Schließen Sie das Programm und starten Sie es erneut über „Als Administrator ausführen“ (Rechtsklick auf das Symbol), dann erneut versuchen.",
            "❌ Se requieren derechos de administrador: cierre el programa y vuelva a iniciarlo con «Ejecutar como administrador» (clic derecho en el icono), luego inténtelo de nuevo.",
            "❌ Sono richiesti i diritti di amministratore: chiudi il programma e riavvialo con «Esegui come amministratore» (clic destro sull'icona), poi riprova."
        ), effacer=True)
        return False

    def _dp_chkdsk_scan(self):
        tr = self.tr
        lecteur = self.diag_drive_menu.get()
        if not self._dp_avertir_si_pas_admin():
            return
        self.dp_ecrire(tr(f"⏳ CHKDSK {lecteur} /scan en cours (lecture seule)...", f"⏳ CHKDSK {lecteur} /scan running (read-only)...",
                          f"⏳ CHKDSK {lecteur} /scan läuft (nur lesend)...", f"⏳ CHKDSK {lecteur} /scan en curso (solo lectura)...",
                          f"⏳ CHKDSK {lecteur} /scan in corso (sola lettura)..."), effacer=True)
        r = subprocess.run(f"chkdsk {lecteur} /scan", shell=True, capture_output=True, text=True, encoding=page_oem(), errors="ignore", creationflags=CREATE_NO_WINDOW)
        sortie = (r.stdout or "") + (r.stderr or "")
        if r.returncode != 0 and ("accès refusé" in sortie.lower() or "access is denied" in sortie.lower() or "zugriff verweigert" in sortie.lower() or "acceso denegado" in sortie.lower() or "accesso negato" in sortie.lower()):
            self.dp_ecrire(tr(
                f"❌ Accès refusé sur {lecteur}. Le logiciel ne semble pas lancé en administrateur (ou les droits ont été révoqués en cours de route). Relancez-le avec « Exécuter en tant qu'administrateur ».",
                f"❌ Access denied on {lecteur}. The software does not appear to be running as administrator (or rights were revoked). Restart it with “Run as administrator”.",
                f"❌ Zugriff verweigert auf {lecteur}. Das Programm scheint nicht als Administrator zu laufen (oder die Rechte wurden entzogen). Starten Sie es erneut über „Als Administrator ausführen“.",
                f"❌ Acceso denegado en {lecteur}. El programa no parece estar ejecutándose como administrador (o se revocaron los derechos). Reinícielo con «Ejecutar como administrador».",
                f"❌ Accesso negato su {lecteur}. Il programma non sembra essere in esecuzione come amministratore (o i diritti sono stati revocati). Riavvialo con «Esegui come amministratore»."
            ))
            return
        self.dp_ecrire(sortie)
        self.noter_action(tr(f"CHKDSK {lecteur} (scan en lecture seule)", f"CHKDSK {lecteur} (read-only scan)", f"CHKDSK {lecteur} (nur lesender Scan)", f"CHKDSK {lecteur} (análisis de solo lectura)", f"CHKDSK {lecteur} (scansione in sola lettura)"))

    def dp_chkdsk_reparer(self):
        tr = self.tr
        lecteur = self.diag_drive_menu.get()
        systeme = lecteur.upper() == os.environ.get("SystemDrive", "C:").upper()
        message = (tr(f"CHKDSK va être PLANIFIÉ sur {lecteur} : il s'exécutera au prochain redémarrage (de quelques minutes à plusieurs heures selon le disque).\n\nContinuer ?",
                      f"CHKDSK will be SCHEDULED on {lecteur}: it runs at the next restart (from a few minutes to several hours depending on the drive).\n\nContinue?",
                      f"CHKDSK wird für {lecteur} GEPLANT: Es läuft beim nächsten Neustart (je nach Laufwerk wenige Minuten bis mehrere Stunden).\n\nFortfahren?",
                      f"CHKDSK se PROGRAMARÁ en {lecteur}: se ejecutará en el próximo reinicio (de unos minutos a varias horas según el disco).\n\n¿Continuar?",
                      f"CHKDSK verrà PIANIFICATO su {lecteur}: verrà eseguito al prossimo riavvio (da pochi minuti a diverse ore a seconda del disco).\n\nContinuare?")
                   if systeme else
                   tr(f"CHKDSK va s'exécuter MAINTENANT sur {lecteur} (réparation + recherche de secteurs défectueux). Cela peut durer de longues heures et le lecteur sera indisponible pendant l'opération.\n\nContinuer ?",
                      f"CHKDSK will run NOW on {lecteur} (repair + bad sector scan). It can take many hours and the drive is unavailable meanwhile.\n\nContinue?",
                      f"CHKDSK läuft JETZT auf {lecteur} (Reparatur + Suche nach defekten Sektoren). Das kann viele Stunden dauern, das Laufwerk ist währenddessen nicht verfügbar.\n\nFortfahren?",
                      f"CHKDSK se ejecutará AHORA en {lecteur} (reparación + búsqueda de sectores defectuosos). Puede tardar muchas horas y la unidad no estará disponible mientras tanto.\n\n¿Continuar?",
                      f"CHKDSK verrà eseguito ORA su {lecteur} (riparazione + ricerca settori danneggiati). Può richiedere molte ore e l'unità non sarà disponibile nel frattempo.\n\nContinuare?"))
        if not messagebox.askyesno("CHKDSK", message):
            return

        def _t():
            if not self._dp_avertir_si_pas_admin():
                return
            self.dp_ecrire(tr(f"⏳ CHKDSK {lecteur} /f /r...", f"⏳ CHKDSK {lecteur} /f /r...", f"⏳ CHKDSK {lecteur} /f /r...", f"⏳ CHKDSK {lecteur} /f /r...", f"⏳ CHKDSK {lecteur} /f /r..."), effacer=True)
            if systeme:
                # Le lecteur système est toujours verrouillé : chkdsk ne peut pas le démonter et
                # demande alors à planifier la vérification au prochain démarrage. Cette question
                # s'affiche dans la langue d'AFFICHAGE de Windows (pas celle choisie dans l'app),
                # ce qui rendait fragile l'ancien pipe de réponses "Y/O/J/S" sur un Windows installé
                # dans une autre langue (il ne tape que la 1ʳᵉ lettre, qui pouvait être refusée).
                # fsutil marque directement le volume comme "dirty", sans aucune question ni
                # dépendance de langue : Windows lancera alors CHKDSK automatiquement au prochain
                # redémarrage, exactement comme si on avait répondu "Oui".
                r = subprocess.run(f'fsutil dirty set {lecteur}:', shell=True, capture_output=True, text=True,
                                   encoding=page_oem(), errors="ignore", creationflags=CREATE_NO_WINDOW)
                self.dp_ecrire((r.stdout or "") + (r.stderr or ""))
                self.dp_ecrire(tr(
                    "✔ Lecteur marqué : CHKDSK s'exécutera automatiquement au prochain démarrage.",
                    "✔ Drive flagged: CHKDSK will run automatically on next restart.",
                    "✔ Laufwerk markiert: CHKDSK wird beim nächsten Neustart automatisch ausgeführt.",
                    "✔ Unidad marcada: CHKDSK se ejecutará automáticamente en el próximo reinicio.",
                    "✔ Unità contrassegnata: CHKDSK verrà eseguito automaticamente al prossimo riavvio."))
            else:
                # Lecteur non-système : pas verrouillé, chkdsk s'exécute directement sans poser
                # de question, donc pas besoin de piper une réponse ni de gérer la langue.
                self.dp_ecrire(tr(
                    "⏳ CHKDSK /f /r peut durer très longtemps sur un grand disque : une fenêtre s'ouvre pour suivre la progression en direct.",
                    "⏳ CHKDSK /f /r can take a very long time on a large drive: a window opens to show live progress.",
                    "⏳ CHKDSK /f /r kann auf einem großen Laufwerk sehr lange dauern: Ein Fenster zeigt den Fortschritt live an.",
                    "⏳ CHKDSK /f /r puede tardar mucho tiempo en una unidad grande: se abre una ventana para ver el progreso en directo.",
                    "⏳ CHKDSK /f /r può richiedere molto tempo su un disco grande: si apre una finestra per seguire l'avanzamento dal vivo."))
                executer_commande_visible(f'chkdsk {lecteur}: /f /r', f"CHKDSK {lecteur}: /f /r - Reparation du disque")
                self.dp_ecrire(tr(
                    f"✔ CHKDSK {lecteur}: /f /r terminé (voir le détail dans la fenêtre qui vient de se fermer).",
                    f"✔ CHKDSK {lecteur}: /f /r completed (see details in the window that just closed).",
                    f"✔ CHKDSK {lecteur}: /f /r abgeschlossen (Details im soeben geschlossenen Fenster).",
                    f"✔ CHKDSK {lecteur}: /f /r completado (consulte el detalle en la ventana que acaba de cerrarse).",
                    f"✔ CHKDSK {lecteur}: /f /r completato (vedere il dettaglio nella finestra appena chiusa)."))
            self.noter_action(tr(f"CHKDSK {lecteur} /f /r " + ("planifié" if systeme else "exécuté"), f"CHKDSK {lecteur} /f /r " + ("scheduled" if systeme else "run"),
                                 f"CHKDSK {lecteur} /f /r " + ("geplant" if systeme else "ausgeführt"), f"CHKDSK {lecteur} /f /r " + ("programado" if systeme else "ejecutado"),
                                 f"CHKDSK {lecteur} /f /r " + ("pianificato" if systeme else "eseguito")))
        self.dp_lancer(_t, self.btn_dp_chk_fix)

