    def dp_voir_journal(self):
        tr = self.tr
        self.diag_textbox.delete("1.0", "end")
        if not os.path.exists(JOURNAL_FILE):
            self.diag_textbox.insert("end", tr("Le journal est vide pour l'instant.\n", "The log is empty for now.\n", "Das Protokoll ist noch leer.\n", "El diario está vacío por ahora.\n", "Il giornale è per ora vuoto.\n"))
            return
        try:
            with open(JOURNAL_FILE, "r", encoding="utf-8") as f:
                lignes = [l for l in f.read().splitlines() if l.strip()][-15:]
        except Exception as e:
            self.diag_textbox.insert("end", f"❌ {e}\n")
            return
        self.diag_textbox.insert("end", "=== " + tr("JOURNAL D'INTERVENTION (15 dernières)", "JOB LOG (last 15)", "AUFTRAGSPROTOKOLL (letzte 15)", "DIARIO DE INTERVENCIONES (últimas 15)", "GIORNALE INTERVENTI (ultimi 15)") + " ===\n\n")
        for l in reversed(lignes):
            try:
                e = json.loads(l)
            except Exception:
                continue
            self.diag_textbox.insert("end", f"📅 {e.get('horodatage', '')}   👤 {e.get('client') or '—'}   🎫 {e.get('ticket') or '—'}\n")
            for a in e.get("actions", []):
                self.diag_textbox.insert("end", f"    • {a.get('heure', '')} {a.get('nom', '')}" + (f" — {a.get('details')}" if a.get("details") else "") + "\n")
            if e.get("notes"):
                self.diag_textbox.insert("end", f"    📝 {e['notes']}\n")
            self.diag_textbox.insert("end", "\n")

