    def dp_donnees_disques(self):
        res = []
        cache = self.charger_cache_disques()
        try:
            volumes = (cache or {}).get("disques", {}).get("volumes", {})
            for lettre, v in sorted(volumes.items()):
                res.append({"lettre": lettre, "label": v.get("label", ""), "free": v.get("free", 0), "total": v.get("total", 0),
                            "frag": v.get("fragmentation", ""), "date": v.get("date_scan")})
        except Exception:
            pass
        return res

