        self.log_textbox = ctk.CTkTextbox(
            self.log_frame, height=100, font=ctk.CTkFont(family="Consolas", size=11)
        )
        self.log_textbox.pack(fill="both", expand=True, padx=10, pady=5)

        # ==========================================
