    def basculer_son(self):
        actif = bool(self.var_son.get())
        enregistrer_son_actif(actif)
        if actif:
            jouer_son_demarrage(force=True)  # aperçu

    def _planifier_ajustement_textes(self, event=None):
        """Regroupe les événements de redimensionnement avant d'ajuster les textes."""
        if event is not None and event.widget is not self:
            return
        if self._ajust_textes_id:
            self.after_cancel(self._ajust_textes_id)
        self._ajust_textes_id = self.after(120, self._ajuster_largeur_textes)

    def _ajuster_largeur_textes(self):
        """Adapte le retour à la ligne des bandeaux et des descriptions à la largeur actuelle."""
        self._ajust_textes_id = None
        try:
            largeur_logique = int(self.winfo_width() / self._get_window_scaling())
            for lbl in self.labels_bandeaux:
                lbl.configure(wraplength=max(300, largeur_logique - 120))
            for lbl in self.labels_desc_utils:
                lbl.configure(wraplength=max(300, largeur_logique - 400))
        except Exception:
            pass

    def _rafraichir_fond_fenetre(self):
        """Réapplique le fond sombre et force un redessin pour éliminer tout résidu blanc."""
        try:
            self.configure(fg_color="#0A0F18")
            self.update_idletasks()
        except Exception:
            pass

