    def reinitialiser_barre_progression(self, message_final=None):
        if not message_final:
            message_final = self.t("status_ready")
        self.after(0, lambda: self.progress_bar.set(1.0))
        self.after(0, lambda: self.progress_label.configure(text=message_final))

        def reset_worker():
            time.sleep(1.5)
            self.after(0, lambda: self.progress_bar.set(0.0))
            self.after(0, lambda: self.progress_label.configure(text=self.t("status_ready")))

        threading.Thread(target=reset_worker, daemon=True).start()

    def bloquer_boutons_taches_lourdes(self):
        self.action_lourde_en_cours = True
        self.after(0, lambda: self.btn_run.configure(state="disabled"))
        self.after(0, lambda: self.btn_scan_disks.configure(state="disabled"))
        self.after(0, lambda: self.btn_optimize_disks.configure(state="disabled"))
        self.after(0, lambda: self.btn_rec_start.configure(state="disabled"))
        self.after(0, lambda: self.btn_rights_only.configure(state="disabled"))

    def debloquer_boutons_taches_lourdes(self, message_final=None):
        if message_final is None:
            message_final = self.tr("Opération terminée avec succès !", "Operation completed successfully!", "Vorgang erfolgreich abgeschlossen!", "¡Operación completada con éxito!", "Operazione completata con successo!")
        self.action_lourde_en_cours = False
        self.after(0, lambda: self.btn_run.configure(state="normal"))
        self.after(0, lambda: self.btn_scan_disks.configure(state="normal"))
        self.after(0, lambda: self.btn_optimize_disks.configure(state="normal"))
        self.after(0, lambda: self.btn_rec_start.configure(state="normal"))
        self.after(0, lambda: self.btn_rights_only.configure(state="normal"))
        self.reinitialiser_barre_progression(message_final)

    def verifier_action_en_cours(self, nom_action):
        if self.action_lourde_en_cours:
            noms = ACTIONS_NOMS.get(nom_action, {})
            nom_affiche = noms.get(self.lang if self.lang in noms else ("fr" if self.lang == "fr" else "en"), nom_action)
            return messagebox.askyesno(
                self.tr("⚠️ Attention", "⚠️ Warning", "⚠️ Warnung", "⚠️ Atención", "⚠️ Attenzione"),
                self.tr(
                    f"Une tâche lourde est en cours.\nLancer '{nom_affiche}' risque de ralentir le système.\n\nContinuer ?",
                    f"A heavy task is currently running.\nStarting '{nom_affiche}' may slow down the system.\n\nContinue?",
                    f"Es läuft derzeit eine aufwendige Aufgabe.\nDas Starten von '{nom_affiche}' kann das System verlangsamen.\n\nFortfahren?",
                    f"Hay una tarea pesada en curso.\nIniciar '{nom_affiche}' puede ralentizar el sistema.\n\n¿Continuar?",
                    f"È in corso un'attività impegnativa.\nAvviare '{nom_affiche}' potrebbe rallentare il sistema.\n\nContinuare?"
                ),
                icon="warning"
            )
        return True

    def set_safe_mode(self):
        try:
            subprocess.run("bcdedit /set {default} safeboot minimal", shell=True, capture_output=True, text=True, creationflags=CREATE_NO_WINDOW)
            messagebox.showinfo(self.tr("Mode sans échec", "Safe Mode", "Abgesicherter Modus", "Modo seguro", "Modalità provvisoria"),
                                self.tr("PC configuré pour démarrer en mode sans échec.", "PC configured for Safe Mode boot.", "Der PC ist für den Start im abgesicherten Modus konfiguriert.", "El PC está configurado para arrancar en modo seguro.", "Il PC è configurato per avviarsi in modalità provvisoria."))
        except Exception as e:
            messagebox.showerror(self.tr("Erreur", "Error", "Fehler", "Error", "Errore"), f"{e}")

    def cancel_safe_mode(self):
        try:
            subprocess.run("bcdedit /deletevalue {default} safeboot", shell=True, capture_output=True, text=True, creationflags=CREATE_NO_WINDOW)
            messagebox.showinfo(self.tr("Mode normal", "Normal Mode", "Normalmodus", "Modo normal", "Modalità normale"),
                                self.tr("Mode sans échec annulé.", "Safe mode cancelled.", "Abgesicherter Modus abgebrochen.", "Modo seguro cancelado.", "Modalità provvisoria annullata."))
        except Exception as e:
            messagebox.showerror(self.tr("Erreur", "Error", "Fehler", "Error", "Errore"), f"{e}")

    def toggle_all_bloat_state(self):
        state = self.chk_all_bloat.get()
        self.all_bloat_checked_state = (state == 1)
        self.tooltip_bloat_global.text = self.t("unselect_all_tt") if self.all_bloat_checked_state else self.t("select_all_tt")
        for pkg, var in self.bloat_vars.items():
            chk = self.bloat_checkboxes.get(pkg)
            if chk and str(chk.cget("state")) != "disabled":
                var.set(self.all_bloat_checked_state)

    def toggle_all_disks_state(self):
        state = self.chk_all_disks.get()
        self.all_disks_checked_state = (state == 1)
        self.tooltip_disks_global.text = self.t("unselect_all_tt") if self.all_disks_checked_state else self.t("select_all_tt")
        for var in self.disk_checkbox_vars.values():
            var.set(self.all_disks_checked_state)

    def toggle_all_runtimes_state(self):
        state = self.chk_all_runtimes.get()
        self.all_runtimes_checked_state = (state == 1)
        self.tooltip_runtimes_global.text = self.t("unselect_all_tt") if self.all_runtimes_checked_state else self.t("select_all_tt")
        for var, _, _ in self.runtime_vars.values():
            var.set(self.all_runtimes_checked_state)

    def initialiser_dossier_rapport(self):
        if not os.path.exists(RAPPORT_DIR):
            try:
                os.makedirs(RAPPORT_DIR)
            except Exception:
                pass

    def charger_cache_disques(self):
        if os.path.exists(CACHE_FILE):
            try:
                with open(CACHE_FILE, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                pass
        return None

    def sauvegarder_cache_disques(self, donnees_disques):
        self.initialiser_dossier_rapport()
        payload = {"disques": donnees_disques}
        try:
            with open(CACHE_FILE, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=4, ensure_ascii=False)
        except Exception:
            pass

    def on_validity_changed(self, choice):
        self.initialiser_onglet_disques_depuis_systeme()

    def calculer_statut_disque(self, date_scan_str, validite_jours):
        if not date_scan_str:
            return self.t("disk_to_optimize"), "gray50"
        try:
            d_scan = datetime.strptime(date_scan_str, "%Y-%m-%d %H:%M:%S")
            expiration = d_scan + timedelta(days=validite_jours)
            maintenant = datetime.now()
            if maintenant > expiration:
                jours_depasse = (maintenant - expiration).days
                return self.t("disk_expired").format(days=jours_depasse), "#E53935"
            else:
                jours_restants = (expiration - maintenant).days
                if jours_restants == 0:
                    return self.t("disk_valid_today"), "#EE5A24"
                else:
                    return self.t("disk_valid_days").format(days=jours_restants), "#EE5A24"
        except Exception:
            return self.t("disk_to_optimize"), "gray50"

    def generate_battery_report(self):
        def run_report():
            report_path = os.path.join(os.environ.get("TEMP", r"C:\Windows\Temp"), "battery_report.html")
            cmd = f'powercfg /batteryreport /output "{report_path}"'
            try:
                # On supprime d'abord un éventuel ancien rapport : sans ça, si powercfg échoue
                # (droits insuffisants, PC sans batterie...), os.path.exists() verrait quand même
                # un fichier — celui d'une exécution précédente — et l'ouvrirait comme si tout
                # s'était bien passé, ce qui aurait induit le technicien en erreur.
                if os.path.exists(report_path):
                    os.remove(report_path)
                res = subprocess.run(cmd, shell=True, capture_output=True, text=True, creationflags=CREATE_NO_WINDOW)
                if os.path.exists(report_path):
                    os.startfile(report_path)
                else:
                    detail = (res.stderr or res.stdout or "").strip()
                    self._afficher_erreur_rapport(
                        self.tr("Rapport de batterie", "Battery report", "Akkubericht", "Informe de batería", "Report batteria"),
                        self.tr(f"Impossible de générer le rapport de batterie.\n\nCe PC n'a peut-être pas de batterie (poste fixe), ou les droits administrateur sont nécessaires.\n\nDétail technique : {detail}",
                                f"Could not generate the battery report.\n\nThis PC may have no battery (desktop), or administrator rights are required.\n\nTechnical detail: {detail}",
                                f"Der Akkubericht konnte nicht erstellt werden.\n\nDieser PC hat eventuell keinen Akku (Desktop-PC), oder es sind Administratorrechte erforderlich.\n\nTechnisches Detail: {detail}",
                                f"No se pudo generar el informe de batería.\n\nEs posible que este PC no tenga batería (equipo de sobremesa), o se requieran permisos de administrador.\n\nDetalle técnico: {detail}",
                                f"Impossibile generare il report della batteria.\n\nQuesto PC potrebbe non avere una batteria (postazione fissa), oppure sono necessari i permessi di amministratore.\n\nDettaglio tecnico: {detail}"))
            except Exception as e:
                self._afficher_erreur_rapport(
                    self.tr("Rapport de batterie", "Battery report", "Akkubericht", "Informe de batería", "Report batteria"),
                    self.tr(f"Erreur inattendue lors de la génération du rapport de batterie :\n{e}",
                            f"Unexpected error while generating the battery report:\n{e}",
                            f"Unerwarteter Fehler bei der Erstellung des Akkuberichts:\n{e}",
                            f"Error inesperado al generar el informe de batería:\n{e}",
                            f"Errore imprevisto durante la generazione del report della batteria:\n{e}"))
        threading.Thread(target=run_report, daemon=True).start()

    def generate_hardware_report(self):
        def run_hw_report():
            if not self.system_hardware_cache:
                self._afficher_erreur_rapport(
                    self.tr("Rapport matériel", "Hardware report", "Hardwarebericht", "Informe de hardware", "Report hardware"),
                    self.tr("Aucune donnée matérielle disponible pour le moment : relancez d'abord « Analyser hardware et composants », puis réessayez.",
                            "No hardware data available yet: run “Analyze hardware and components” first, then try again.",
                            "Noch keine Hardwaredaten verfügbar: Führen Sie zuerst „Hardware und Komponenten analysieren“ aus und versuchen Sie es erneut.",
                            "Todavía no hay datos de hardware disponibles: ejecute primero «Analizar hardware y componentes» y vuelva a intentarlo.",
                            "Nessun dato hardware ancora disponibile: esegui prima «Analizza hardware e componenti», poi riprova."))
                return
            html_content = f"<html><body><pre>{self.system_hardware_cache}</pre></body></html>"
            temp_path = os.path.join(os.environ.get("TEMP", r"C:\Windows\Temp"), "hardware_report.html")
            try:
                with open(temp_path, "w", encoding="utf-8") as f:
                    f.write(html_content)
                os.startfile(temp_path)
            except Exception as e:
                self._afficher_erreur_rapport(
                    self.tr("Rapport matériel", "Hardware report", "Hardwarebericht", "Informe de hardware", "Report hardware"),
                    self.tr(f"Impossible de créer ou d'ouvrir le rapport matériel :\n{e}",
                            f"Could not create or open the hardware report:\n{e}",
                            f"Der Hardwarebericht konnte nicht erstellt oder geöffnet werden:\n{e}",
                            f"No se pudo crear o abrir el informe de hardware:\n{e}",
                            f"Impossibile creare o aprire il report hardware:\n{e}"))
        threading.Thread(target=run_hw_report, daemon=True).start()

    def _afficher_erreur_rapport(self, titre, message):
        """Affiche une erreur de génération de rapport de façon thread-safe (appelé depuis un
        thread de fond) : sans ce messagebox, un échec de powercfg/écriture fichier se traduisait
        par un bouton qui ne faisait visiblement rien, sans aucune explication pour le technicien."""
        self.after(0, lambda: messagebox.showerror(titre, message))

    def start_refresh_bloat_thread(self):
        self.btn_refresh_bloat.configure(state="disabled")
        threading.Thread(target=self.run_refresh_bloatware, daemon=True).start()

    def start_sys_info_thread(self):
        self.btn_scan_sys.configure(state="disabled")
        threading.Thread(target=self._worker_sys_info_scan, daemon=True).start()

    def _worker_sys_info_scan(self):
        self.after(0, lambda: self.progress_label.configure(text=self.tr("⏳ Analyse du matériel...", "⏳ Hardware analysis...", "⏳ Hardwareanalyse...", "⏳ Análisis del hardware...", "⏳ Analisi dell'hardware...")))
        self.after(0, lambda: self.progress_bar.set(0.0))
        self.after(0, lambda: self.sys_textbox.delete("1.0", "end"))

        lb = HW_LABELS.get(self.lang, HW_LABELS["en"])

        def _ligne(cle):  # libellé de ligne aligné sur 12 caractères
            return f"{lb[cle]:<12}"

        title_header = lb["title"]
        lbl_os = lb["os"]
        lbl_cpu = lb["cpu"]
        lbl_mobo = lb["mobo"]
        lbl_ram = lb["ram"]
        lbl_gpu = lb["gpu"]
        lbl_batt = lb["batt"]
        lbl_disks = lb["disks"]

        lbl_cores = lb["cores_of"]
        lbl_threads = "Threads"
        lbl_sticks = lb["sticks"]
        lbl_power = _ligne("r_power")
        lbl_charge = _ligne("r_charge")
        lbl_health = _ligne("r_health")

        col_disk = lb["col_disk"]
        col_letters = lb["col_letters"]
        col_model = lb["col_model"]
        col_type = "Type"
        col_health_status = lb["col_health"]
        col_hours = lb["col_hours"]
        col_temp = lb["col_temp"]

        ps_script = (
            "$OutputEncoding = [System.Text.Encoding]::UTF8;"
            "[Console]::OutputEncoding = [System.Text.Encoding]::UTF8;"
            "$cpu = Get-CimInstance Win32_Processor | Select-Object -First 1 Name, NumberOfCores, NumberOfLogicalProcessors;"
            "$mobo = Get-CimInstance Win32_BaseBoard | Select-Object -First 1 Manufacturer, Product, Version;"
            "$os = Get-CimInstance Win32_OperatingSystem | Select-Object -First 1 Caption, OSArchitecture, Version;"
            "$ram_sticks = Get-CimInstance Win32_PhysicalMemory;"
            "$ram_total_gb = [math]::Round(($ram_sticks | Measure-Object Capacity -Sum).Sum / 1GB, 2);"
            "$ram_type_code = ($ram_sticks | Select-Object -First 1).SMBIOSMemoryType;"
            "$ram_type = switch ($ram_type_code) { 20 {'DDR'} 21 {'DDR2'} 24 {'DDR3'} 26 {'DDR4'} 34 {'DDR5'} default {'DDR'} };"
            "$ram_speed = ($ram_sticks | Select-Object -First 1).Speed;"
            "$ram_count = ($ram_sticks | Measure-Object).Count;"
            "$gpus = Get-CimInstance Win32_VideoController;"
            "$activePlanObj = Get-CimInstance -Namespace root\\cimv2\\power -ClassName Win32_PowerPlan -ErrorAction SilentlyContinue | Where-Object { $_.IsActive -eq $true };"
            "$powerPlan = if ($activePlanObj) { $activePlanObj.ElementName } else { '@@POWER_DEFAULT@@' };"
            "$batt = Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue;"
            "$battStatus = '@@BATT_NA@@';"
            "$battHealth = 'N/A';"
            "if ($batt) {"
            "  $statusMap = @{1='@@ST1@@'; 2='@@ST2@@'; 3='@@ST3@@'; 4='@@ST4@@'; 5='@@ST5@@'};"
            "  $chargeState = if ($statusMap.ContainsKey([int]$batt.BatteryStatus)) { $statusMap[[int]$batt.BatteryStatus] } else { '@@ST2@@' };"
            "  $battStatus = ($batt.EstimatedChargeRemaining.ToString() + '% [' + $chargeState + ']');"
            "  try {"
            "    $bFull = (Get-CimInstance -Namespace root\\wmi -ClassName BatteryFullChargedCapacity -ErrorAction SilentlyContinue).FullChargedCapacity;"
            "    $bDesign = (Get-CimInstance -Namespace root\\wmi -ClassName BatteryStaticData -ErrorAction SilentlyContinue).DesignedCapacity;"
            "    if ($bFull -and $bDesign -and $bDesign -gt 0) {"
            "      $wear = [math]::Round((1 - ($bFull / $bDesign)) * 100, 1);"
            "      $health = [math]::Round(($bFull / $bDesign) * 100, 1);"
            "      $battHealth = ($health.ToString() + '% (@@WEAR@@: ' + $wear.ToString() + '%)')"
            "    }"
            "  } catch {}"
            "};"
            "$physicalDisks = Get-PhysicalDisk;"
            "Write-Host '========================================================================================';"
            f"Write-Host '                    {title_header}                              ';"
            "Write-Host '========================================================================================';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_os}';"
            "Write-Host ('    > @@R_SYSTEM@@: ' + $os.Caption + ' (' + $os.OSArchitecture + ') Build ' + $os.Version);"
            "Write-Host '----------------------------------------------------------------------------------------';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_cpu}';"
            "Write-Host ('    > @@R_MODEL@@: ' + $cpu.Name.Trim());"
            f"Write-Host ('    > @@R_CORES@@: ' + $cpu.NumberOfCores + ' {lbl_cores} ' + $cpu.NumberOfLogicalProcessors + ' {lbl_threads}');"
            "Write-Host '----------------------------------------------------------------------------------------';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_mobo}';"
            "Write-Host ('    > @@R_MAKER@@: ' + $mobo.Manufacturer);"
            "Write-Host ('    > @@R_MODEL@@: ' + $mobo.Product);"
            "Write-Host ('    > @@R_REVISION@@: ' + $mobo.Version);"
            "Write-Host '----------------------------------------------------------------------------------------';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_ram}';"
            f"Write-Host ('    > @@R_CAPACITY@@: ' + $ram_total_gb + ' @@GB@@ ' + $ram_type + ' (' + $ram_count + ' {lbl_sticks})');"
            "Write-Host ('    > @@R_FREQ@@: ' + $ram_speed + ' MHz');"
            "Write-Host '----------------------------------------------------------------------------------------';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_gpu}';"
            "$vramMap = @{};"
            "Get-ItemProperty 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Class\\{4d36e968-e325-11ce-bfc1-08002be10318}\\*' -ErrorAction SilentlyContinue | ForEach-Object {"
            "  $desc = $_.DriverDesc;"
            "  $raw = $_.'HardwareInformation.qwMemorySize';"
            "  if ($desc -and $raw) {"
            "    $val = 0;"
            "    if ($raw -is [byte[]]) { if ($raw.Length -ge 8) { $val = [BitConverter]::ToInt64($raw, 0) } }"
            "    else { try { $val = [int64]$raw } catch {} }"
            "    if ($val -gt 0) { $vramMap[$desc] = $val }"
            "  }"
            "};"
            "foreach ($g in $gpus) {"
            "  $gName = $g.Name;"
            "  $bytes = 0;"
            "  if ($vramMap.ContainsKey($gName)) { $bytes = $vramMap[$gName] }"
            "  if ($bytes -le 0 -and $g.AdapterRAM) { try { $bytes = [int64]$g.AdapterRAM } catch {} }"
            "  $vram_val = if ($bytes -gt 0) { [string][math]::Round($bytes / 1GB, 1) + ' @@GB@@' } else { 'N/A' };"
            "  Write-Host ('    > @@R_MODEL@@: ' + $gName + ' (' + $vram_val + ' VRAM)');"
            "};"
            "Write-Host '----------------------------------------------------------------------------------------';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_batt}';"
            f"Write-Host ('    > {lbl_power}: ' + $powerPlan);"
            f"Write-Host ('    > {lbl_charge}: ' + $battStatus);"
            f"Write-Host ('    > {lbl_health}: ' + $battHealth);"
            "Write-Host '----------------------------------------------------------------------------------------';"
            "Write-Host '';"
            f"Write-Host '[+] {lbl_disks}';"
            f"'{{0,-10}} {{1,-10}} {{2,-35}} {{3,-12}} {{4,-10}} {{5,-8}} {{6,-8}}' -f '{col_disk}', '{col_letters}', '{col_model}', '{col_type}', '{col_health_status}', '{col_hours}', '{col_temp}';"
            "Write-Host ('-' * 95);"
            "foreach ($pd in $physicalDisks) {"
            "  $diskNum = '@@DISK_UNKNOWN@@';"
            "  try {"
            "    $diskObj = Get-Disk -Number $pd.DeviceId -ErrorAction SilentlyContinue;"
            "    if ($diskObj) { $diskNum = '@@DISK_PREFIX@@' + $diskObj.Number }"
            "  } catch {}"
            "  $letters = @();"
            "  try {"
            "    $parts = Get-Partition -DiskNumber $pd.DeviceId -ErrorAction SilentlyContinue;"
            "    foreach($p in $parts) { if ($p.DriveLetter) { $letters += ($p.DriveLetter + ':') } }"
            "  } catch {}"
            '  $letterStr = if ($letters.Count -gt 0) { "[" + ($letters -join ", ") + "]" } else { "@@LETTERS_NONE@@" };'
            "  $typeStr = if ($pd.BusType -eq 'NVMe') { 'SSD NVMe' } elseif ($pd.MediaType -and $pd.MediaType -ne 'Unspecified') { $pd.MediaType } else { 'HDD' };"
            "  $counter = $pd | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue;"
            "  $hoursVal = if ($counter -and $counter.PowerOnHours -ne $null) { $counter.PowerOnHours.ToString() + 'h' } else { 'N/A' };"
            "  $tempVal = if ($counter -and $counter.Temperature -ne $null) { $($counter.Temperature).ToString() + '°C' } else { 'N/A' };"
            "  $rawHealth = if ($pd.HealthStatus) { $pd.HealthStatus } else { 'Healthy' };"
            "  $healthStr = if ($rawHealth -eq 'Healthy') { '@@HEALTHY@@' } else { $rawHealth };"
            "  '{0,-10} {1,-10} {2,-35} {3,-12} {4,-10} {5,-8} {6,-8}' -f $diskNum, $letterStr, $pd.FriendlyName, $typeStr, $healthStr, $hoursVal, $tempVal"
            "};"
            "Write-Host '========================================================================================';"
        )

        ps_script = appliquer_jetons(ps_script, lb)

        try:
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            process = subprocess.Popen(
                ['powershell.exe', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', ps_script],
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="ignore",
                startupinfo=startupinfo,
            )
            output, _ = process.communicate()
            self.system_hardware_cache = output
            self.after(0, lambda: self.sys_textbox.insert("end", output + "\n"))
        except Exception as e:
            err_msg = self.tr(f"❌ Erreur détection matériel: {str(e)}\n", f"❌ Hardware detection error: {str(e)}\n", f"❌ Fehler bei der Hardwareerkennung: {str(e)}\n", f"❌ Error de detección del hardware: {str(e)}\n", f"❌ Errore di rilevamento dell'hardware: {str(e)}\n")
            self.system_hardware_cache = err_msg
            self.after(0, lambda: self.sys_textbox.insert("end", err_msg))

        self.after(0, self.initialiser_onglet_disques_depuis_systeme)
        self.after(0, lambda: self.btn_scan_sys.configure(state="normal"))
        self.log_info(self.tr("✔ Analyse système et matériel terminée.", "✔ System & Hardware analysis completed.", "✔ System- und Hardwareanalyse abgeschlossen.", "✔ Análisis del sistema y del hardware completado.", "✔ Analisi del sistema e dell'hardware completata."))
        self.reinitialiser_barre_progression()

    def initialiser_onglet_disques_depuis_systeme(self):
        self.disks_textbox.delete("1.0", "end")
        title_smart_str = self.tr("=== RAPPORT S.M.A.R.T. & SANTÉ DES VOLUMES ===", "=== S.M.A.R.T. & VOLUMES HEALTH REPORT ===", "=== BERICHT: S.M.A.R.T. & ZUSTAND DER VOLUMES ===", "=== INFORME S.M.A.R.T. Y ESTADO DE LOS VOLÚMENES ===", "=== REPORT S.M.A.R.T. E STATO DEI VOLUMI ===")
        self.disks_textbox.insert("end", f"{title_smart_str}\n\n")

        for widget in self.disks_selection_frame.winfo_children():
            widget.destroy()
        self.disk_checkbox_vars.clear()
        self.disk_checkbox_widgets.clear()

        validite_jours = 15 if "15" in self.validity_combo.get() else 30
        cache = self.charger_cache_disques() or {}
        disques_data = cache.get("disques", {}) if isinstance(cache, dict) else {}
        
        if isinstance(disques_data, dict):
            cache_volumes = disques_data.get("volumes", {})
            smart_raw = disques_data.get("smart_raw", self.tr("Cliquez sur '1. Analyser les Disques (Audit)' pour lancer le diagnostic S.M.A.R.T.\n", "Click '1. Scan Disks (Audit)' to perform diagnostic.\n", "Klicken Sie auf '1. Laufwerke analysieren (Audit)', um die S.M.A.R.T.-Diagnose zu starten.\n", "Haga clic en '1. Analizar discos (Auditoría)' para iniciar el diagnóstico S.M.A.R.T.\n", "Fare clic su '1. Analizza i dischi (Audit)' per avviare la diagnostica S.M.A.R.T.\n"))
        else:
            cache_volumes = {}
            smart_raw = self.tr("Cliquez sur '1. Analyser les Disques (Audit)' pour lancer le diagnostic S.M.A.R.T.\n", "Click '1. Scan Disks (Audit)' to perform diagnostic.\n", "Klicken Sie auf '1. Laufwerke analysieren (Audit)', um die S.M.A.R.T.-Diagnose zu starten.\n", "Haga clic en '1. Analizar discos (Auditoría)' para iniciar el diagnóstico S.M.A.R.T.\n", "Fare clic su '1. Analizza i dischi (Audit)' per avviare la diagnostica S.M.A.R.T.\n")

        self.disks_textbox.insert("end", smart_raw + "\n")

        for letter in string.ascii_uppercase:
            drive_path = f"{letter}:\\"
            if os.path.exists(drive_path):
                try:
                    if ctypes.windll.kernel32.GetDriveTypeW(ctypes.c_wchar_p(drive_path)) == 3:
                        vol_name = ctypes.create_unicode_buffer(261)
                        ctypes.windll.kernel32.GetVolumeInformationW(
                            ctypes.c_wchar_p(drive_path), vol_name, ctypes.sizeof(vol_name), None, None, None, None, 0
                        )
                        label = vol_name.value if vol_name.value else (self.tr("Disque Local", "Local Disk", "Lokaler Datenträger", "Disco local", "Disco locale"))
                        
                        try:
                            total_b, _, free_b = shutil.disk_usage(drive_path)
                            free_str = self.format_size(free_b)
                            total_str = self.format_size(total_b)
                        except Exception:
                            free_str, total_str = "?", "?"

                        frag_rate = self.tr("[Audit requis]", "[Audit required]", "[Audit erforderlich]", "[Auditoría requerida]", "[Audit richiesto]")
                        date_scan_str = None
                        if isinstance(cache_volumes, dict) and letter in cache_volumes:
                            v_info = cache_volumes[letter]
                            if isinstance(v_info, dict):
                                frag_rate = v_info.get("fragmentation", frag_rate)
                                date_scan_str = v_info.get("date_scan", None)

                        statut_texte, _ = self.calculer_statut_disque(date_scan_str, validite_jours)
                        display_text = f"{self.t('disk_drive_label')} {letter}: [{label}] ({free_str} / {total_str}) | Frag: {frag_rate} | {statut_texte}"

                        var = ctk.BooleanVar(value=self.all_disks_checked_state)
                        chk = ctk.CTkCheckBox(
                            self.disks_selection_frame, 
                            text=display_text, 
                            variable=var,
                            font=ctk.CTkFont(size=11)
                        )
                        chk.pack(anchor="w", padx=10, pady=3)
                        
                        self.disk_checkbox_vars[letter] = var
                        self.disk_checkbox_widgets[letter] = chk
                except Exception:
                    pass

    def run_refresh_bloatware(self):
        self.log_info(self.tr("Vérification des bloatwares installés...", "Checking installed bloatware...", "Installierte Bloatware wird geprüft...", "Comprobando el bloatware instalado...", "Controllo del bloatware installato..."))
        self.after(0, lambda: self.progress_bar.set(0.0))
        
        total_items = len(BLOATWARE_LIST)
        for idx, item in enumerate(BLOATWARE_LIST, start=1):
            prog = idx / total_items
            self.after(0, lambda p=prog: self.progress_bar.set(p))
            
            pkg = item["package"]
            name = item["name"]
            chk = self.bloat_checkboxes.get(pkg)
            var = self.bloat_vars.get(pkg)
            if not chk or not var:
                continue

            ps_check = f"(Get-AppxPackage -AllUsers {pkg} -ErrorAction SilentlyContinue) -ne $null"
            cmd = f'powershell.exe -Command "{ps_check}"'
            try:
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                res = subprocess.run(cmd, capture_output=True, text=True, shell=True, startupinfo=startupinfo)
                is_installed = "True" in res.stdout

                def update_ui(c, v, n, installed):
                    if installed:
                        c.configure(text=n, state="normal", text_color=("gray10", "gray90"))
                    else:
                        c.configure(text=f"{n} {self.t('bloat_already_removed')}", state="disabled", text_color="gray50")
                        v.set(False)

                self.after(0, lambda c=chk, v=var, n=name, inst=is_installed: update_ui(c, v, n, inst))
            except Exception:
                pass

        self.log_info(self.tr("✔ Liste des bloatwares mise à jour.", "✔ Bloatware list updated.", "✔ Bloatware-Liste aktualisiert.", "✔ Lista de bloatware actualizada.", "✔ Elenco del bloatware aggiornato."))
        self.after(0, lambda: self.btn_refresh_bloat.configure(state="normal"))
        self.reinitialiser_barre_progression()

    def log_info(self, message):
        # Thread-safe : ces logs sont appelés depuis des threading.Thread de fond
        # (run_maintenance, run_bloatware_removal, run_disk_scan, etc.). Tkinter/CTk
        # n'est pas thread-safe, donc on passe systématiquement par self.after()
        # pour que l'écriture widget se fasse bien sur le thread principal.
        ts = time.strftime("[%H:%M:%S] ")
        def _do():
            self.log_textbox.insert("end", ts + message + "\n")
            self.log_textbox.see("end")
        self.after(0, _do)

    def rec_log(self, message):
        ts = time.strftime("[%H:%M:%S] ")
        def _do():
            self.rec_textbox.insert("end", ts + message + "\n")
            self.rec_textbox.see("end")
        self.after(0, _do)

    def runtime_log(self, message):
        ts = time.strftime("[%H:%M:%S] ")
        def _do():
            self.runtime_textbox.insert("end", ts + message + "\n")
            self.runtime_textbox.see("end")
        self.after(0, _do)

    def lancer_utilitaire_externe(self, filename, name):
        assets_dir = get_assets_path()
        target_path = os.path.join(assets_dir, filename)
        if not os.path.exists(target_path):
            target_path = get_resource_path(filename)
        if os.path.exists(target_path):
            try:
                subprocess.Popen(f'"{target_path}"', shell=True, cwd=os.path.dirname(target_path))
            except Exception as e:
                messagebox.showerror(self.tr("Erreur", "Error", "Fehler", "Error", "Errore"),
                                     self.tr(f"Impossible de lancer {name} :\n{e}", f"Could not launch {name}:\n{e}", f"{name} konnte nicht gestartet werden:\n{e}", f"No se pudo iniciar {name}:\n{e}", f"Impossibile avviare {name}:\n{e}"))
        else:
            messagebox.showwarning(self.tr("Fichier manquant", "File Missing", "Datei fehlt", "Archivo ausente", "File mancante"),
                                   self.tr(f"{filename} introuvable.", f"{filename} not found.", f"{filename} wurde nicht gefunden.", f"No se ha encontrado {filename}.", f"{filename} non trovato."))

