    def run_apply_dns(self):
        selected_profile_name = self.dns_combo.get()
        profile_data = self.dns_profiles_map.get(selected_profile_name)

        if not profile_data:
            self.log_info(self.tr("❌ Erreur de profil.", "❌ Profile Error.", "❌ Profilfehler.", "❌ Error de perfil.", "❌ Errore del profilo."))
            self.debloquer_boutons_taches_lourdes()
            self.after(0, lambda: self.btn_apply_dns.configure(state="normal"))
            return

        self.after(0, lambda: self.progress_bar.set(0.2))
        self.log_info(self.tr(f"\n=== APPLICATION DU PROFIL DNS : {selected_profile_name} ===",
                              f"\n=== APPLYING DNS PROFILE: {selected_profile_name} ===",
                              f"\n=== DNS-PROFIL WIRD ANGEWENDET: {selected_profile_name} ===",
                              f"\n=== APLICANDO EL PERFIL DNS: {selected_profile_name} ===",
                              f"\n=== APPLICAZIONE DEL PROFILO DNS: {selected_profile_name} ==="))

        self.dns_sauver_etat()  # mémorise les DNS d'avant : bouton « Annuler »
        if profile_data["type"] == "dhcp":
            ps_cmd = (
                "$interfaces = Get-NetAdapter | Where-Object { $_.Status -eq 'Up' };"
                "foreach ($adapter in $interfaces) {"
                "  Set-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -ResetServerAddresses -ErrorAction SilentlyContinue;"
                "}"
            )
        else:
            ipv4_list = profile_data.get("ipv4", [])
            ipv6_list = profile_data.get("ipv6", [])
            self.after(0, lambda: self.progress_bar.set(0.5))
            code, sortie = executer_powershell(ps_appliquer_dns(ipv4_list, ipv6_list), timeout=120)
            self.after(0, lambda: self.progress_bar.set(0.8))
            subprocess.run("ipconfig /flushdns", shell=True, capture_output=True, creationflags=CREATE_NO_WINDOW)
            lignes, ok = analyser_resultat_dns(sortie, self.tr, avec_v6=bool(ipv6_list))
            for niveau, texte in lignes:
                self.log_info(ICONES_NIVEAU.get(niveau, "") + " " + texte)
            if ok:
                self.noter_action(self.tr("Profil DNS appliqué (IPv4 + IPv6)", "DNS profile applied (IPv4 + IPv6)", "DNS-Profil angewendet (IPv4 + IPv6)", "Perfil DNS aplicado (IPv4 + IPv6)", "Profilo DNS applicato (IPv4 + IPv6)"), selected_profile_name)
                self.log_info(self.tr("🎉 Profil DNS appliqué (IPv4 + IPv6) et cache vidé.", "🎉 DNS profile applied (IPv4 + IPv6) and cache flushed.", "🎉 DNS-Profil (IPv4 + IPv6) angewendet und Cache geleert.", "🎉 Perfil DNS (IPv4 + IPv6) aplicado y caché vaciada.", "🎉 Profilo DNS (IPv4 + IPv6) applicato e cache svuotata."))
            else:
                self.log_info(self.tr("⚠️ Application incomplète : voir le détail ci-dessus. Le guide manuel IPv6 plus bas reste utilisable.", "⚠️ Incomplete: see details above. The manual IPv6 guide below is still usable.", "⚠️ Unvollständig: siehe Details oben. Die manuelle IPv6-Anleitung unten bleibt nutzbar.", "⚠️ Incompleto: vea el detalle arriba. La guía manual IPv6 de abajo sigue siendo válida.", "⚠️ Incompleto: vedi i dettagli sopra. La guida manuale IPv6 qui sotto resta utilizzabile."))
            self.debloquer_boutons_taches_lourdes()
            self.after(0, lambda: self.btn_apply_dns.configure(state="normal"))
            return

        self.after(0, lambda: self.progress_bar.set(0.6))
        try:
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            subprocess.run(
                f'powershell.exe -Command "{ps_cmd}"',
                capture_output=True,
                text=True,
                shell=True,
                encoding="utf-8",
                errors="ignore",
                startupinfo=startupinfo
            )
            self.after(0, lambda: self.progress_bar.set(0.8))
            subprocess.run("ipconfig /flushdns", shell=True, capture_output=True, creationflags=CREATE_NO_WINDOW)

            self.noter_action(self.tr("Profil DNS appliqué", "DNS profile applied", "DNS-Profil angewendet", "Perfil DNS aplicado", "Profilo DNS applicato"), selected_profile_name)
            self.log_info(self.tr("🎉 Profil DNS appliqué et cache vidé.", "🎉 DNS profile applied and cache flushed.", "🎉 DNS-Profil angewendet und Cache geleert.", "🎉 Perfil DNS aplicado y caché vaciada.", "🎉 Profilo DNS applicato e cache svuotata."))
            self.debloquer_boutons_taches_lourdes()
        except Exception as e:
            self.log_info(self.tr(f"❌ Erreur DNS : {e}", f"❌ DNS Error: {e}", f"❌ DNS-Fehler: {e}", f"❌ Error de DNS: {e}", f"❌ Errore DNS: {e}"))
            self.debloquer_boutons_taches_lourdes()

        self.after(0, lambda: self.btn_apply_dns.configure(state="normal"))

