        self.dp_ecrire("=== " + tr("CLÉ WINDOWS (OEM)", "WINDOWS KEY (OEM)", "WINDOWS-SCHLÜSSEL (OEM)", "CLAVE DE WINDOWS (OEM)", "CHIAVE WINDOWS (OEM)") + " ===", effacer=True)
